    { const char * tb_v2254 = "        if (++tb_vcol == 80) { tb_vcol = 0; tb_vrow++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2254; }
    { const char * tb_v2255 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2255; }
