    { const char * tb_v2257 = "        for (int i = 0; i < 24 * 80; i++) tb_vga[i] = tb_vga[i + 80];\n"; *(const char * *)tb_grow(v_lines) = tb_v2257; }
    { const char * tb_v2258 = "        for (int i = 24 * 80; i < 25 * 80; i++) tb_vga[i] = (unsigned short)(tb_vcolor << 8 | ' ');\n"; *(const char * *)tb_grow(v_lines) = tb_v2258; }
