    { const char * tb_v2383 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2383; }
    { const char * tb_v2384 = "// выход: QEMU с -device isa-debug-exit закрывается, без него процессор просто спит\n"; *(const char * *)tb_grow(v_lines) = tb_v2384; }
    { const char * tb_v2385 = "__attribute__((noreturn)) static void exit(int code) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2385; }
