    { const char * tb_v2389 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2389; }
    { const char * tb_v2390 = "// память: запас 64 МБ. Куски по размерам 16, 32, 64, ... байт; отданный кусок\n"; *(const char * *)tb_grow(v_lines) = tb_v2390; }
    { const char * tb_v2391 = "// кладётся в корзину своего размера и выдаётся снова. Последний кусок отдаётся сразу.\n"; *(const char * *)tb_grow(v_lines) = tb_v2391; }
    { const char * tb_v2392 = "#define TB_HEAP (64 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v2392; }
