    { const char * tb_v2401 = "// прерывания и службы. Обычные клетки упираются раньше — и службы живут, даже когда клетки съели всё\n"; *(const char * *)tb_grow(v_lines) = tb_v2401; }
    { const char * tb_v2402 = "#define TB_RESERVE (8 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v2402; }
