    { const char * tb_v2697 = "TB_API double pow(double a, double b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2697; }
    { const char * tb_v2698 = "    if (b == 0) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2698; }
