    { const char * tb_v2709 = "TB_API void *bsearch(const void *key, const void *base, size_t n, size_t size, int (*cmp)(const void *, const void *)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2709; }
    { const char * tb_v2710 = "    size_t lo = 0, hi = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2710; }
