    { const char * tb_v3129 = "// --- владение памятью (обменная куча, как в старой Омниум): у куска один хозяин — клетка.\n"; *(const char * *)tb_grow(v_lines) = tb_v3129; }
    { const char * tb_v3130 = "// Что уходит из клетки (аргументы background, текст в канале, список через move), становится\n"; *(const char * *)tb_grow(v_lines) = tb_v3130; }
    { const char * tb_v3131 = "// ничьим (метка 0, «ядро») или переходит получателю. Упала клетка — ядро возвращает всё, что\n"; *(const char * *)tb_grow(v_lines) = tb_v3131; }
    { const char * tb_v3132 = "// у неё осталось: этого больше никто не видит.\n"; *(const char * *)tb_grow(v_lines) = tb_v3132; }
