    { const char * tb_v3640 = "    GetSystemInfo(&si);\n"; *(const char * *)tb_grow(v_lines) = tb_v3640; }
    { const char * tb_v3641 = "    return (long)si.dwNumberOfProcessors;\n"; *(const char * *)tb_grow(v_lines) = tb_v3641; }
    { const char * tb_v3642 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3642; }
    { const char * tb_v3643 = "#define fopen(p, m) tb_win_fopen(p, m)\n"; *(const char * *)tb_grow(v_lines) = tb_v3643; }
    { const char * tb_v3644 = "#define stat(p, s) tb_win_stat(p, s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3644; }
    { const char * tb_v3645 = "#define mkdir(p, mode) tb_win_mkdir(p)\n"; *(const char * *)tb_grow(v_lines) = tb_v3645; }
    { const char * tb_v3646 = "#define rmdir(p) tb_win_rmdir(p)\n"; *(const char * *)tb_grow(v_lines) = tb_v3646; }
    { const char * tb_v3647 = "#define unlink(p) tb_win_unlink(p)\n"; *(const char * *)tb_grow(v_lines) = tb_v3647; }
    { const char * tb_v3648 = "#define rename(a, b) tb_win_rename(a, b)\n"; *(const char * *)tb_grow(v_lines) = tb_v3648; }
    { const char * tb_v3649 = "#define getenv(n) tb_win_getenv(n)\n"; *(const char * *)tb_grow(v_lines) = tb_v3649; }
