    { const char * tb_v3651 = "#undef pclose\n"; *(const char * *)tb_grow(v_lines) = tb_v3651; }
    { const char * tb_v3652 = "#define popen(c, m) tb_win_popen(c, m)\n"; *(const char * *)tb_grow(v_lines) = tb_v3652; }
    { const char * tb_v3653 = "#define pclose(f) _pclose(f)\n"; *(const char * *)tb_grow(v_lines) = tb_v3653; }
    { const char * tb_v3654 = "#define DIR tb_win_dir\n"; *(const char * *)tb_grow(v_lines) = tb_v3654; }
    { const char * tb_v3655 = "#define dirent tb_win_dirent\n"; *(const char * *)tb_grow(v_lines) = tb_v3655; }
    { const char * tb_v3656 = "#define opendir(p) tb_win_opendir(p)\n"; *(const char * *)tb_grow(v_lines) = tb_v3656; }
    { const char * tb_v3657 = "#define readdir(d) tb_win_readdir(d)\n"; *(const char * *)tb_grow(v_lines) = tb_v3657; }
    { const char * tb_v3658 = "#define closedir(d) tb_win_closedir(d)\n"; *(const char * *)tb_grow(v_lines) = tb_v3658; }
    { const char * tb_v3659 = "#define isatty(fd) tb_win_isatty(fd)\n"; *(const char * *)tb_grow(v_lines) = tb_v3659; }
    { const char * tb_v3660 = "#define sysconf(x) tb_win_sysconf(x)\n"; *(const char * *)tb_grow(v_lines) = tb_v3660; }
    { const char * tb_v3661 = "#define localtime_r(t, r) (localtime_s((r), (t)) == 0 ? (r) : 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v3661; }
    { const char * tb_v3662 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3662; }
    { const char * tb_v3663 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3663; }
    { const char * tb_v3664 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3664; }
    { const char * tb_v3665 = "// подсказки для clang / gcc: ошибка бывает редко, а tb_crash не возвращается\n"; *(const char * *)tb_grow(v_lines) = tb_v3665; }
    { const char * tb_v3666 = "#if defined(__GNUC__)\n"; *(const char * *)tb_grow(v_lines) = tb_v3666; }
    { const char * tb_v3667 = "#define TB_RARE(x) __builtin_expect(!!(x), 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v3667; }
    { const char * tb_v3668 = "#define TB_COLD __attribute__((cold, noreturn, noinline))\n"; *(const char * *)tb_grow(v_lines) = tb_v3668; }
    { const char * tb_v3669 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3669; }
    { const char * tb_v3670 = "#define TB_RARE(x) (x)\n"; *(const char * *)tb_grow(v_lines) = tb_v3670; }
    { const char * tb_v3671 = "#define TB_COLD\n"; *(const char * *)tb_grow(v_lines) = tb_v3671; }
    { const char * tb_v3672 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3672; }
    { const char * tb_v3673 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3673; }
    { const char * tb_v3674 = "// список: кусок памяти, len элементов по size байт, место на cap\n"; *(const char * *)tb_grow(v_lines) = tb_v3674; }
    { const char * tb_v3675 = "typedef struct { char *data; long long len; long long cap; long long size; } tb_list;\n"; *(const char * *)tb_grow(v_lines) = tb_v3675; }
    { const char * tb_v3676 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3676; }
    { const char * tb_v3677 = "// ---------- язык сообщений: русский или английский ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3677; }
    { const char * tb_v3678 = "// TB_LANG=en/ru, иначе файл ~/.tachbit/lang (его пишет tb lang en/ru), иначе язык системы (LANG).\n"; *(const char * *)tb_grow(v_lines) = tb_v3678; }
    { const char * tb_v3679 = "// tb_tr заменяет русские куски сообщения английскими по таблице tb_lang_tab.\n"; *(const char * *)tb_grow(v_lines) = tb_v3679; }
    { const char * tb_v3680 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3680; }
    { const char * tb_v3681 = "#define tb_tr(s) (s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3681; }
    { const char * tb_v3682 = "#define tb_lang_en() 0\n"; *(const char * *)tb_grow(v_lines) = tb_v3682; }
    { const char * tb_v3683 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3683; }
    { const char * tb_v3684 = "// ---- TB_LANG_TAB (сделано tools/embed_lang.py, не правь руками) ----\n"; *(const char * *)tb_grow(v_lines) = tb_v3684; }
    { const char * tb_v3685 = "static const char *const tb_lang_tab[] = {\n"; *(const char * *)tb_grow(v_lines) = tb_v3685; }
    { const char * tb_v3686 = "    \"кусок живёт только внутри своего цикла: его можно читать и менять по номеру, ходить по нему each и передавать в функцию, но нельзя сохранять, растить .add и уменьшать .pop\", \"a piece lives only inside its loop: you can read and change it by number, go over it with each and pass it to a function, but you cannot keep it, grow it with .add or shrink it with .pop\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3686; }
    { const char * tb_v3687 = "    \"в background функция получает только int, dec, bool, text и channel (а список — через move: f(move xs)): списки и obj могли бы меняться сразу из двух мест\", \"in background a function gets only int, dec, bool, text and channel (and a list via move: f(move xs)): lists and obj could be changed from two places at once\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3687; }
    { const char * tb_v3688 = "    \"внутри on all cores эта функция меняет полученный список или obj, а он снаружи цикла: собери свой список или obj внутри цикла и передай его\", \"inside on all cores this function changes a list or obj it got, and that one is outside the loop: make your own list or obj inside the loop and pass it\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3688; }
    { const char * tb_v3689 = "    \"для ядра нужен clang (или инструменты LLVM: opt, llc, llvm-link): на Mac — xcode-select --install, на Linux — apt install clang\", \"a kernel needs clang (or LLVM tools: opt, llc, llvm-link): on Mac — xcode-select --install, on Linux — apt install clang\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3689; }
    { const char * tb_v3690 = "    \"пока жив ярлык на элемент этого списка или dict, его нельзя растить и уменьшать: память переедет, и ярлык поведёт в пустоту\", \"while a link to an element of this list or dict is alive, it cannot grow or shrink: the memory would move and the link would point to nothing\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3690; }
    { const char * tb_v3691 = "    \"из dict нельзя убирать ключи, пока по нему идёт each: часть ключей пропустится. Собери ключи в список и убери после цикла\", \"you cannot remove keys from a dict while each goes over it: some keys would be skipped. Collect the keys in a list and remove them after the loop\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3691; }
    { const char * tb_v3692 = "    \"этот список уже отдан в background через move: им больше пользоваться нельзя (можно дать ему новое значение: xs = [1, 2])\", \"this list was already given to background with move: it cannot be used any more (you can give it a new value: xs = [1, 2])\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3692; }
    { const char * tb_v3693 = "    \"через move пока отдают список или dict из int, dec, bool, text или channel: obj внутри могли бы быть видны ещё откуда-то\", \"for now move gives away only a list or dict of int, dec, bool, text or channel: obj inside could be seen from somewhere else\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3693; }
    { const char * tb_v3694 = "    \"draw_round(x, y, ширина, высота, радиус, \\\"углы\\\", цвет)  — углы: \\\"\\\" все, \\\"top\\\", \\\"bottom\\\", \\\"left\\\", \\\"right\\\", \\\"tl tr bl br\\\"\", \"draw_round(x, y, width, height, radius, \\\"corners\\\", color)  — corners: \\\"\\\" all, \\\"top\\\", \\\"bottom\\\", \\\"left\\\", \\\"right\\\", \\\"tl tr bl br\\\"\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3694; }
    { const char * tb_v3695 = "    \"внутри temp не видно списков, dict и obj снаружи (кроме списков чисел): создай данные внутри temp или передай числа\", \"lists, dict and obj from outside are not seen inside temp (except number lists): make the data inside temp or pass numbers\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3695; }
    { const char * tb_v3696 = "    \"у gpu func параметры int, dec, bool, а первым может быть p: pixel (точка), v: corner (угол) или s: screen (экран)\", \"gpu func parameters are int, dec, bool, and the first can be p: pixel, v: corner or s: screen\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3696; }
    { const char * tb_v3697 = "    \"эту shared меняет функция, которая идёт параллельно (background или on all cores): меняй её под замком  lock имя\", \"this shared is changed by a function that runs in parallel (background or on all cores): change it under a lock  lock name\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3697; }
    { const char * tb_v3698 = "    \"эта функция меняет список, а на его элемент смотрит живой ярлык: если список вырастет, ярлык поведёт в пустоту\", \"this function changes a list while a live link looks at its element: if the list grows, the link would point to nothing\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3698; }
    { const char * tb_v3699 = "    \"в цикле через move отдают только список, созданный в этом же шаге цикла: иначе на следующем шаге его уже нет\", \"in a loop move gives away only a list made in this same loop step: otherwise it is gone on the next step\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3699; }
    { const char * tb_v3700 = "    \"в функцию отдают ярлык на элемент списка и сам список: если функция вырастит список, ярлык поведёт в пустоту\", \"the function gets a link to a list element and the list itself: if the function grows the list, the link would point to nothing\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3700; }
    { const char * tb_v3701 = "    \"  tachbit app    файл.tb   сделать программу для Омниума (файл.oapp); --own — своим машинным кодом, без LLVM\", \"  tachbit app    file.tb   make a program for Omnium (file.oapp); --own — own machine code, without LLVM\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3701; }
    { const char * tb_v3702 = "    \"этот список виден ещё откуда-то (второе имя или лежит в другом списке/obj): move отдал бы его сразу двоим\", \"this list is seen from somewhere else (a second name, or it lies in another list/obj): move would give it to two at once\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3702; }
    { const char * tb_v3703 = "    \"в gpu func можно звать только встроенные числовые функции (sin, cos, mix, noise ...) и другие gpu func\", \"in gpu func you can call only built-in number functions (sin, cos, mix, noise ...) and other gpu func\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3703; }
    { const char * tb_v3704 = "    \"из temp наружу можно сохранить только int, dec или bool: текст, списки и obj удалятся в конце блока\", \"only int, dec or bool can be kept outside temp: texts, lists and obj are deleted at the end of the block\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3704; }
    { const char * tb_v3705 = "    \"spot_light(номер 0…7, x, y, z, куда x, куда y, куда z, ширина в градусах, цвет, дальность) — фонарь\", \"spot_light(number 0…7, x, y, z, look x, look y, look z, width in degrees, color, range) — a spotlight\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3705; }
    { const char * tb_v3706 = "    \" нельзя менять списки и obj снаружи цикла и то, что из них взято (свои, созданные внутри, — можно)\", \" you cannot change lists and obj from outside the loop, or what was taken from them (your own, made inside, are fine)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3706; }
    { const char * tb_v3707 = "    \"подключение C-файлов через link будет в версии 0.9 (вместе с danger); файлы Tachbit подключает use\", \"connecting C files with link will come in version 0.9 (together with danger); use connects Tachbit files\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3707; }
    { const char * tb_v3708 = "    \"mouse_lock(true)  —  мышь для игр от первого лица: курсора нет, поворот — mouse_dx() и mouse_dy()\", \"mouse_lock(true)  —  mouse for first-person games: no cursor, turning — mouse_dx() and mouse_dy()\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3708; }
    { const char * tb_v3709 = "    \"у этого значения нет методов: они есть у списков (.add .pop) и dict (.has .remove .keys .values)\", \"this value has no methods: lists have them (.add .pop) and dict (.has .remove .keys .values)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3709; }
    { const char * tb_v3710 = "    \"программа упала: ошибка памяти. Это ошибка Tachbit, а не твоя: пришли, пожалуйста, эту программу\", \"the program crashed: memory error. This is a Tachbit bug, not yours: please send this program\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3710; }
    { const char * tb_v3711 = "    \"skip и stop внутри lock работают только для циклов внутри lock: иначе замок останется закрытым\", \"skip and stop inside lock work only for loops inside lock: otherwise the lock would stay closed\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3711; }
    { const char * tb_v3712 = "    \"не получилось собрать библиотеку. Это ошибка Tachbit, а не твоя: твой код прошёл все проверки.\", \"could not build the library. This is a Tachbit bug, not yours: your code passed all checks.\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3712; }
    { const char * tb_v3713 = "    \"unlock пишется прямо в блоке lock, не внутри if и циклов: так всегда ясно, взят замок или нет\", \"unlock is written right in the lock block, not inside if or loops: that way it is always clear whether the lock is taken\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3713; }
    { const char * tb_v3714 = "    \"не получилось собрать программу. Это ошибка Tachbit, а не твоя: твой код прошёл все проверки.\", \"could not build the program. This is a Tachbit bug, not yours: your code passed all checks.\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3714; }
    { const char * tb_v3715 = "    \", а где-то наоборот — две работы могут ждать друг друга вечно. Бери их везде в одном порядке\", \", and somewhere the other way — two jobs can wait for each other forever. Take them in the same order everywhere\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3715; }
    { const char * tb_v3716 = "    \"  --llvm / --c   к build / run: собрать через LLVM (так и есть, если есть clang) или через C\", \"  --llvm / --c   for build / run: build through LLVM (the default if there is clang) or through C\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3716; }
    { const char * tb_v3717 = "    \"через move отдают только свою переменную, созданную в этой функции (не параметр и не ярлык)\", \"move gives away only your own variable made in this function (not a parameter and not a link)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3717; }
    { const char * tb_v3718 = "    \"внутри lock return нельзя: замок останется закрытым; сохрани число снаружи и выйди из блока\", \"return is not allowed inside lock: the lock would stay closed; save the number outside and leave the block\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3718; }
    { const char * tb_v3719 = "    \"ярлык на элемент list bool нельзя: там каждый элемент — один бит, у бита нет своего адреса\", \"a link to an element of list bool is not allowed: each element there is one bit, and a bit has no address of its own\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3719; }
    { const char * tb_v3720 = "    \"функция вызывает сама себя раньше первого return со значением: поставь простой return выше\", \"the function calls itself before its first return with a value: put a simple return above\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3720; }
    { const char * tb_v3721 = "    \"внутри each ... by N return нельзя: сохрани число в переменную снаружи и выйди через stop\", \"return is not allowed inside each ... by N: save the number in an outside variable and leave with stop\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3721; }
    { const char * tb_v3722 = "    \"mouse_wheel()  →  на сколько шагов повернули колёсико: + вперёд, − назад, 0 — не крутили\", \"mouse_wheel()  →  how many steps the wheel turned: + forward, − back, 0 — not turned\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3722; }
    { const char * tb_v3723 = "    \"shadows(размер) — тени от солнца в квадрате размер × размер вокруг камеры; 0 — без теней\", \"shadows(size) — sun shadows in a size × size square around the camera; 0 — no shadows\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3723; }
    { const char * tb_v3724 = "    \"light_shadow(лампа 0…7, true) — лампа даёт тени на сетки со своими шейдерами (до 4 ламп)\", \"light_shadow(lamp 0…7, true) — the lamp casts shadows on meshes with their own shaders (up to 4 lamps)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3724; }
    { const char * tb_v3725 = "    \"функция for c не может заканчиваться ошибкой: C не умеет её поймать; верни, например, -1\", \"a for c function cannot end with an error: C cannot catch it; return, for example, -1\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3725; }
    { const char * tb_v3726 = "    \"mesh_bounds(сетка, x, y, z, радиус) — шар, из которого сетка не выходит (для отсечения)\", \"mesh_bounds(mesh, x, y, z, radius) — a ball the mesh never leaves (for culling)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3726; }
    { const char * tb_v3727 = "    \"mesh_free(сетка) — сетка больше не нужна: память отдаётся, номер достанется новой сетке\", \"mesh_free(mesh) — the mesh is not needed any more: memory is freed, the number goes to a new mesh\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3727; }
    { const char * tb_v3728 = "    \"функция может закончиться ошибкой: напиши  try f(),  f() or запасное  или  f() else err\", \"the function can end with an error: write  try f(),  f() or fallback  or  f() else err\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3728; }
    { const char * tb_v3729 = "    \"shared внутри on all cores можно только менять через += или -=, а читать — после цикла\", \"shared inside on all cores can only be changed with += or -=, and read after the loop\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3729; }
    { const char * tb_v3730 = "    \"функция с fail в background пока нельзя: пусть она отдаёт текст ошибки обычным выходом\", \"a function with fail cannot go to background yet: let it give the error text as a normal output\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3730; }
    { const char * tb_v3731 = "    \"у поля shape пишется размер: u8, u16, u32, u64, i8, i16, i32, i64, bits N или bytes N\", \"a shape field has a size: u8, u16, u32, u64, i8, i16, i32, i64, bits N or bytes N\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3731; }
    { const char * tb_v3732 = "    \"число не помещается в int: больше 9223372036854775807 или меньше -9223372036854775808\", \"the number does not fit in int: more than 9223372036854775807 or less than -9223372036854775808\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3732; }
    { const char * tb_v3733 = "    \"ярлык на элемент списка колонок нельзя: возьми ярлык на качество, например pts[i].x\", \"a link to an element of a column list is not allowed: take a link to a field, for example pts[i].x\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3733; }
    { const char * tb_v3734 = "    \"это может закончиться ошибкой: напиши  try ...,  ... or запасное  или  ... else err\", \"this can end with an error: write  try ...,  ... or fallback  or  ... else err\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3734; }
    { const char * tb_v3735 = "    \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\", \"a list cannot grow while each ... by N goes over it (and the piece itself cannot grow)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3735; }
    { const char * tb_v3736 = "    \"shader_image(сетка, слот 0…3, картинка) — картинка для tex_r(слот, u, v) в шейдере\", \"shader_image(mesh, slot 0…3, picture) — a picture for tex_r(slot, u, v) in the shader\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3736; }
    { const char * tb_v3737 = "    \"снаружи функций можно писать только use, func, gpu func, obj, enum, shape и shared\", \"outside functions you can write only use, func, gpu func, obj, enum, shape and shared\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3737; }
    { const char * tb_v3738 = "    \"шейдер точки, угла или экрана сам не зовут: его ставят mesh_shader и screen_shader\", \"a pixel, corner or screen shader is not called directly: mesh_shader and screen_shader set it\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3738; }
    { const char * tb_v3739 = "    \"draw_image_alpha(картинка, x, y)  — с настоящей прозрачностью (мягкие края, тени)\", \"draw_image_alpha(picture, x, y)  — with real transparency (soft edges, shadows)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3739; }
    { const char * tb_v3740 = "    \"draw_shadow(x, y, ширина, высота, скругление, размер, цвет)  — мягкая тень вокруг\", \"draw_shadow(x, y, width, height, rounding, size, color)  — a soft shadow around\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3740; }
    { const char * tb_v3741 = "    \"  tb start имя [слова]     собрать проект и запустить (без имени — текущая папка)\", \"  tb start name [words]    build the project and run it (no name — current folder)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3741; }
    { const char * tb_v3742 = "    \"  tachbit lib    файл.tb   библиотека для C: libфайл.a и файл.h (функции с for c)\", \"  tachbit lib    file.tb   a library for C: libfile.a and file.h (functions with for c)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3742; }
    { const char * tb_v3743 = "    \": это не адрес из new_mem или блок уже освобождён (точнее покажет TB_MEM_CHECK=1)\", \": this is not an address from new_mem or the block is already freed (TB_MEM_CHECK=1 will show more)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3743; }
    { const char * tb_v3744 = "    \"mesh_shader(сетка, \\\"water\\\") — свой шейдер (gpu func) на сетку; \\\"\\\" — обычный свет\", \"mesh_shader(mesh, \\\"water\\\") — your own shader (gpu func) on a mesh; \\\"\\\" — normal light\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3744; }
    { const char * tb_v3745 = "    \"bone_box(сетка, кость, x1, y1, z1, x2, y2, z2) — углы в коробке слушаются кости\", \"bone_box(mesh, bone, x1, y1, z1, x2, y2, z2) — corners in the box follow the bone\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3745; }
    { const char * tb_v3746 = "    \"key_down(\\\"left\\\")  — стрелки left right up down, space, enter, escape, буквы \\\"a\\\"\", \"key_down(\\\"left\\\")  — arrows left right up down, space, enter, escape, letters \\\"a\\\"\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3746; }
    { const char * tb_v3747 = "    \"функции C зовут внутри danger: C может испортить память, Tachbit её не проверит\", \"C functions are called inside danger: C can spoil memory, Tachbit will not check it\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3747; }
    { const char * tb_v3748 = "    \"внутри temp background нельзя: память блока удалится, пока функция ещё работает\", \"background is not allowed inside temp: the block memory would be deleted while the function still works\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3748; }
    { const char * tb_v3749 = "    \"в by vec переменную, которую копишь через += или -=, нельзя читать внутри цикла\", \"in by vec a variable accumulated with += or -= cannot be read inside the loop\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3749; }
    { const char * tb_v3750 = "    \"image_from_mem(адрес, байт)  →  номер картинки (PNG, JPEG, BMP, GIF из памяти)\", \"image_from_mem(address, bytes)  →  picture number (PNG, JPEG, BMP, GIF from memory)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3750; }
    { const char * tb_v3751 = "    \"mesh_add_uv(сетка, x1, y1, z1, u1, v1, x2, y2, z2, u2, v2, x3, y3, z3, u3, v3)\", \"mesh_add_uv(mesh, x1, y1, z1, u1, v1, x2, y2, z2, u2, v2, x3, y3, z3, u3, v3)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3751; }
    { const char * tb_v3752 = "    \"point_light(номер 0…7, x, y, z, цвет, дальность) — лампа светит во все стороны\", \"point_light(number 0…7, x, y, z, color, range) — a lamp shining in all directions\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3752; }
    { const char * tb_v3753 = "    \"fog(цвет, с какого расстояния, где уже весь цвет) — fog(0, 0, 0) убирает туман\", \"fog(color, from what distance, where it is all color) — fog(0, 0, 0) removes fog\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3753; }
    { const char * tb_v3754 = "    \"внутри temp return нельзя: сохрани число в переменную снаружи и выйди из блока\", \"return is not allowed inside temp: save the number in an outside variable and leave the block\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3754; }
    { const char * tb_v3755 = "    \"shared снаружи функций начинается с числа или true/false: shared ticks = int 0\", \"shared outside functions starts with a number or true/false: shared ticks = int 0\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3755; }
    { const char * tb_v3756 = "    \"bone_quat(сетка, кость, x, y, z, w) — поворот кости кватернионом (как в glTF)\", \"bone_quat(mesh, bone, x, y, z, w) — turn the bone by a quaternion (as in glTF)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3756; }
    { const char * tb_v3757 = "    \"()  →  на сколько точек сдвинули мышь с прошлого раза (вправо и вниз — плюс)\", \"()  →  how many points the mouse moved since last time (right and down — plus)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3757; }
    { const char * tb_v3758 = "    \"этот замок уже взят выше: второй lock с тем же именем ждал бы сам себя вечно\", \"this lock is already taken above: a second lock with the same name would wait for itself forever\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3758; }
    { const char * tb_v3759 = "    \"нет такого размера: u8, u16, u32, u64, i8, i16, i32, i64, bits N или bytes N\", \"no such size: u8, u16, u32, u64, i8, i16, i32, i64, bits N or bytes N\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3759; }
    { const char * tb_v3760 = "    \"ядро пока не собрать (это ошибка Tachbit, а не твоя): в LLVM не переводится \", \"the kernel cannot be built yet (this is a Tachbit bug, not yours): LLVM cannot translate \",\n"; *(const char * *)tb_grow(v_lines) = tb_v3760; }
    { const char * tb_v3761 = "    \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: \", \"TB_GPU_CHECK: blending on this GPU is not round-to-nearest: \",\n"; *(const char * *)tb_grow(v_lines) = tb_v3761; }
    { const char * tb_v3762 = "    \"функция с таким именем есть в двух модулях, напиши модуль: money.total(...)\", \"a function with this name is in two modules, name the module: money.total(...)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3762; }
    { const char * tb_v3763 = "    \" нельзя менять переменную снаружи: сделай её shared и меняй через += или -=\", \" you cannot change an outside variable: make it shared and change it with += or -=\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3763; }
    { const char * tb_v3764 = "    \" нельзя менять списки и obj снаружи цикла (свои, созданные внутри, — можно)\", \" you cannot change lists and obj outside the loop (your own, made inside, are fine)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3764; }
    { const char * tb_v3765 = "    \"у функции с несколькими gives return пишется без значения: он отдаёт выходы\", \"in a function with several gives, return is written without a value: it gives the outputs\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3765; }
    { const char * tb_v3766 = "    \"после background (service) пишется вызов функции: a = background load(name)\", \"after background (service) comes a function call: a = background load(name)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3766; }
    { const char * tb_v3767 = "    \"window_sharp()  —  до window_open: окно в настоящих точках экрана (Retina)\", \"window_sharp()  —  before window_open: the window in real screen points (Retina)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3767; }
    { const char * tb_v3768 = "    \" try нельзя: ядро не может остановить всю функцию, пиши  or  или  else err\", \" try is not allowed: the core cannot stop the whole function, write  or  or  else err\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3768; }
    { const char * tb_v3769 = "    \"по каналу each идёт просто: each x in ch (без on all cores, by vec и by N)\", \"each over a channel goes simply: each x in ch (without on all cores, by vec and by N)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3769; }
    { const char * tb_v3770 = "    \"у самого shape есть только size (сколько байт); поля читают у адреса: p = \", \"shape itself has only size (how many bytes); fields are read at an address: p = \",\n"; *(const char * *)tb_grow(v_lines) = tb_v3770; }
    { const char * tb_v3771 = "    \"window_use(окно)  —  рисовать, мышь и клавиши — в этом окне (0 — главное)\", \"window_use(window)  —  drawing, mouse and keys go to this window (0 — the main one)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3771; }
    { const char * tb_v3772 = "    \"внутри lock each по каналу нельзя: пока ждёшь, замок держат все остальные\", \"each over a channel is not allowed inside lock: while you wait, everyone else is held by the lock\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3772; }
    { const char * tb_v3773 = "    \"прерывания бывают только в ядре без ОС: собери файл командой tachbit bare\", \"interrupts exist only in a kernel without an OS: build the file with tachbit bare\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3773; }
    { const char * tb_v3774 = "    \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\", \"the stack is full: a function calls itself too deep (endless recursion?)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3774; }
    { const char * tb_v3775 = "    \"blur_rect(x, y, ширина, высота, сила)  — размыть то, что уже нарисовано\", \"blur_rect(x, y, width, height, strength)  — blur what is already drawn\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3775; }
    { const char * tb_v3776 = "    \"mesh_image(сетка, картинка) — картинка из load_image; -1 — без картинки\", \"mesh_image(mesh, picture) — a picture from load_image; -1 — no picture\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3776; }
    { const char * tb_v3777 = "    \"screen_shader(\\\"glow\\\") — пропустить весь кадр через gpu func с s: screen\", \"screen_shader(\\\"glow\\\") — pass the whole frame through a gpu func with s: screen\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3777; }
    { const char * tb_v3778 = "    \"внутри by vec нельзя менять переменную снаружи: копи её через += или -=\", \"inside by vec you cannot change an outside variable: accumulate it with += or -=\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3778; }
    { const char * tb_v3779 = "    \"не получилось скачать (нет сети, нет curl или сервер ответил ошибкой): \", \"could not download (no network, no curl or the server answered with an error): \",\n"; *(const char * *)tb_grow(v_lines) = tb_v3779; }
    { const char * tb_v3780 = "    \"слева от = через запятую пишутся имена, ячейки xs[i] или качества u.age\", \"left of = come names, cells xs[i] or fields u.age, separated by commas\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3780; }
    { const char * tb_v3781 = "    \"draw_mesh_rot(сетка, x, y, z, поворот, наклон, крен) — углы в градусах\", \"draw_mesh_rot(mesh, x, y, z, turn, tilt, roll) — angles in degrees\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3781; }
    { const char * tb_v3782 = "    \"pad_axis(0, \\\"lx\\\")  →  от -1 до 1: lx ly rx ry; курки l2 r2 — от 0 до 1\", \"pad_axis(0, \\\"lx\\\")  →  from -1 to 1: lx ly rx ry; triggers l2 r2 — from 0 to 1\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3782; }
    { const char * tb_v3783 = "    \" читает кадр только в самом шейдере экрана (s: screen), не в помощнике\", \" reads the frame only in the screen shader itself (s: screen), not in a helper\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3783; }
