    { const char * tb_v3882 = "    \"clipboard_get()  →  текст из буфера обмена (\\\"\\\" — пусто)\", \"clipboard_get()  →  text from the clipboard (\\\"\\\" — empty)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3882; }
    { const char * tb_v3883 = "    \"mesh_alpha(сетка, 0…1) — прозрачность: 1 — непрозрачная\", \"mesh_alpha(mesh, 0…1) — transparency: 1 — solid\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3883; }
