    { const char * tb_v4595 = "TB_COLD TB_API void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4595; }
    { const char * tb_v4596 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4596; }
    { const char * tb_v4597 = "    if (tb_cell_can_fall()) tb_cell_fall(msg, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4597; }
    { const char * tb_v4598 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4598; }
    { const char * tb_v4599 = "    fflush(stdout);\n"; *(const char * *)tb_grow(v_lines) = tb_v4599; }
