    { const char * tb_v4837 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4837; }
    { const char * tb_v4838 = "// длина последних текстов: s[i] в цикле не пересчитывает strlen каждый раз\n"; *(const char * *)tb_grow(v_lines) = tb_v4838; }
    { const char * tb_v4839 = "TB_API _Thread_local const char *tb_lc_p[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v4839; }
