    { const char * tb_v4873 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4873; }
    { const char * tb_v4874 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4874; }
    { const char * tb_v4875 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4875; }
    { const char * tb_v4876 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4876; }
    { const char * tb_v4877 = "TB_API void tb_gc_free(void *p) { free(p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4877; }
