    { const char * tb_v4882 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4882; }
    { const char * tb_v4883 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4883; }
    { const char * tb_v4884 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4884; }
