    { const char * tb_v4926 = "    tb_gready = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4926; }
    { const char * tb_v4927 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4927; }
    { const char * tb_v4928 = "TB_INL tb_gpage *tb_gmap_get(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4928; }
    { const char * tb_v4929 = "    if (a >> 48) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4929; }
    { const char * tb_v4930 = "    tb_gpage **l2 = tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v4930; }
