    { const char * tb_v4933 = "TB_API void tb_gmap_put(uintptr_t a, tb_gpage *pg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4933; }
    { const char * tb_v4934 = "    tb_gpage ***d = &tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v4934; }
    { const char * tb_v4935 = "    if (!*d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4935; }
    { const char * tb_v4936 = "        *d = calloc(1 << 16, sizeof(tb_gpage *));\n"; *(const char * *)tb_grow(v_lines) = tb_v4936; }
    { const char * tb_v4937 = "        if (!*d) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4937; }
    { const char * tb_v4938 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4938; }
    { const char * tb_v4939 = "    (*d)[(a >> TB_GSH) & 0xFFFF] = pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v4939; }
    { const char * tb_v4940 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4940; }
    { const char * tb_v4941 = "TB_API void tb_gmap_add(tb_gpage *pg, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4941; }
    { const char * tb_v4942 = "    for (long long o = 0; o < size; o += TB_GPG) tb_gmap_put((uintptr_t)pg->start + o, pg);\n"; *(const char * *)tb_grow(v_lines) = tb_v4942; }
