    { const char * tb_v4951 = "// Windows: VirtualAlloc тоже даёт нули, и адрес у него всегда кратен 64 КБ — обрезать нечего.\n"; *(const char * *)tb_grow(v_lines) = tb_v4951; }
    { const char * tb_v4952 = "// munmap здесь зовётся только для целого куска из tb_gsys — это VirtualFree(MEM_RELEASE).\n"; *(const char * *)tb_grow(v_lines) = tb_v4952; }
    { const char * tb_v4953 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4953; }
