    { const char * tb_v5619 = "    return tb_u8text(s + b, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v5619; }
    { const char * tb_v5620 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5620; }
    { const char * tb_v5621 = "// each ch in s: буква с байта *i; *i становится последним байтом буквы (цикл сам прибавит 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v5621; }
    { const char * tb_v5622 = "TB_API const char *tb_u8take(const char *s, long long *i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5622; }
    { const char * tb_v5623 = "    const unsigned char *p = (const unsigned char *)s + *i;\n"; *(const char * *)tb_grow(v_lines) = tb_v5623; }
    { const char * tb_v5624 = "    if (*p < 0x80) return tb_chr(*p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5624; }
    { const char * tb_v5625 = "    long long k = tb_u8n(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5625; }
    { const char * tb_v5626 = "    *i += k - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5626; }
