    { const char * tb_v5628 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5628; }
    { const char * tb_v5629 = "// s += b: дописать в конец своей памяти s, а не собирать третий текст из двух.\n"; *(const char * *)tb_grow(v_lines) = tb_v5629; }
    { const char * tb_v5630 = "// *rl — длина s в своей памяти (-1: своей памяти нет, s могли сохранить где-то ещё — сначала копия),\n"; *(const char * *)tb_grow(v_lines) = tb_v5630; }
    { const char * tb_v5631 = "// *rc — сколько там места.\n"; *(const char * *)tb_grow(v_lines) = tb_v5631; }
    { const char * tb_v5632 = "TB_API void tb_app_n(const char **p, long long *rl, long long *rc, const char *b, long long lb);\n"; *(const char * *)tb_grow(v_lines) = tb_v5632; }
    { const char * tb_v5633 = "// число цифрами в конец буфера d[24]: вернёт начало цифр, длину — в *n\n"; *(const char * *)tb_grow(v_lines) = tb_v5633; }
    { const char * tb_v5634 = "TB_INL const char *tb_digits(long long x, char *d, long long *n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5634; }
    { const char * tb_v5635 = "    unsigned long long u = x < 0 ? 0ULL - (unsigned long long)x : (unsigned long long)x;\n"; *(const char * *)tb_grow(v_lines) = tb_v5635; }
    { const char * tb_v5636 = "    char *p = d + 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v5636; }
    { const char * tb_v5637 = "    do { *--p = (char)('0' + u % 10); u /= 10; } while (u);\n"; *(const char * *)tb_grow(v_lines) = tb_v5637; }
    { const char * tb_v5638 = "    if (x < 0) *--p = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v5638; }
    { const char * tb_v5639 = "    *n = d + 24 - p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5639; }
    { const char * tb_v5640 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5640; }
    { const char * tb_v5641 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5641; }
    { const char * tb_v5642 = "TB_INL void tb_app(const char **p, long long *rl, long long *rc, const char *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5642; }
    { const char * tb_v5643 = "    tb_app_n(p, rl, rc, b, (long long)strlen(b));\n"; *(const char * *)tb_grow(v_lines) = tb_v5643; }
    { const char * tb_v5644 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5644; }
    { const char * tb_v5645 = "// дописать число: цифры пишутся прямо в конец, без отдельного текста\n"; *(const char * *)tb_grow(v_lines) = tb_v5645; }
    { const char * tb_v5646 = "TB_INL void tb_app_i(const char **p, long long *rl, long long *rc, long long x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5646; }
    { const char * tb_v5647 = "    char d[24]; int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5647; }
    { const char * tb_v5648 = "    unsigned long long u = x < 0 ? 0ULL - (unsigned long long)x : (unsigned long long)x;\n"; *(const char * *)tb_grow(v_lines) = tb_v5648; }
    { const char * tb_v5649 = "    do { d[23 - n++] = (char)('0' + u % 10); u /= 10; } while (u);\n"; *(const char * *)tb_grow(v_lines) = tb_v5649; }
    { const char * tb_v5650 = "    if (x < 0) d[23 - n++] = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v5650; }
    { const char * tb_v5651 = "    tb_app_n(p, rl, rc, d + 24 - n, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v5651; }
    { const char * tb_v5652 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5652; }
    { const char * tb_v5653 = "TB_API void tb_app_n(const char **p, long long *rl, long long *rc, const char *b, long long lb);\n"; *(const char * *)tb_grow(v_lines) = tb_v5653; }
    { const char * tb_v5654 = "// ядро отдаёт свой кусок в общий текст: если общий ещё пустой — забирает память куска целиком, без копии\n"; *(const char * *)tb_grow(v_lines) = tb_v5654; }
    { const char * tb_v5655 = "TB_API void tb_app_take(const char **p, long long *rl, long long *rc, const char *b, long long brl, long long brc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5655; }
    { const char * tb_v5656 = "    if (*rl < 0 && (*p)[0] == 0 && brl >= 0) { *p = b; *rl = brl; *rc = brc; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5656; }
    { const char * tb_v5657 = "    tb_app_n(p, rl, rc, b, brl >= 0 ? brl : (long long)strlen(b));\n"; *(const char * *)tb_grow(v_lines) = tb_v5657; }
    { const char * tb_v5658 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5658; }
    { const char * tb_v5659 = "TB_API void tb_app_n(const char **p, long long *rl, long long *rc, const char *b, long long lb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5659; }
    { const char * tb_v5660 = "    char *s = (char *)*p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5660; }
    { const char * tb_v5661 = "    if (*rl < 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5661; }
    { const char * tb_v5662 = "        long long la = (long long)strlen(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v5662; }
    { const char * tb_v5663 = "        long long cap = 2 * (la + lb) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5663; }
    { const char * tb_v5664 = "        if (cap < 64) cap = 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v5664; }
    { const char * tb_v5665 = "        char *r = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v5665; }
    { const char * tb_v5666 = "        memcpy(r, s, la);\n"; *(const char * *)tb_grow(v_lines) = tb_v5666; }
    { const char * tb_v5667 = "        memcpy(r + la, b, lb);\n"; *(const char * *)tb_grow(v_lines) = tb_v5667; }
    { const char * tb_v5668 = "        r[la + lb] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5668; }
    { const char * tb_v5669 = "        *p = r; *rl = la + lb; *rc = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v5669; }
    { const char * tb_v5670 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5670; }
    { const char * tb_v5671 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5671; }
    { const char * tb_v5672 = "    long long need = *rl + lb + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5672; }
    { const char * tb_v5673 = "    if (need > *rc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5673; }
    { const char * tb_v5674 = "        long long cap = 2 * need;\n"; *(const char * *)tb_grow(v_lines) = tb_v5674; }
    { const char * tb_v5675 = "        long long off = (b >= s && b < s + *rc) ? b - s : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5675; }
