    { const char * tb_v6332 = "TB_API double tb_m_ceil(double x, int line) { (void)line; return ceil(x); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6332; }
    { const char * tb_v6333 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6333; }
    { const char * tb_v6334 = "// ---------- sort ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6334; }
    { const char * tb_v6335 = "TB_API int tb_cmp_int(const void *a, const void *b) { long long x = *(const long long *)a, y = *(const long long *)b; return (x > y) - (x < y); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6335; }
    { const char * tb_v6336 = "TB_API int tb_cmp_dec(const void *a, const void *b) { double x = *(const double *)a, y = *(const double *)b; return (x > y) - (x < y); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6336; }
