    { const char * tb_v6338 = "TB_API tb_list *tb_copy(tb_list *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6338; }
    { const char * tb_v6339 = "    if (l->size == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6339; }
    { const char * tb_v6340 = "        tb_list *r = tb_mem(sizeof(tb_list));\n"; *(const char * *)tb_grow(v_lines) = tb_v6340; }
    { const char * tb_v6341 = "        long long bytes = l->cap / 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v6341; }
    { const char * tb_v6342 = "        r->len = l->len; r->cap = l->cap; r->size = 0; r->data = tb_mem_np(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v6342; }
    { const char * tb_v6343 = "        memcpy(r->data, l->data, bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v6343; }
    { const char * tb_v6344 = "        return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6344; }
