    { const char * tb_v6594 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6594; }
    { const char * tb_v6595 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6595; }
