    { const char * tb_v6600 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6600; }
    { const char * tb_v6601 = "// a = service f(): в программе с ОС служба — тот же background (запас памяти есть только в ядре)\n"; *(const char * *)tb_grow(v_lines) = tb_v6601; }
    { const char * tb_v6602 = "TB_API void tb_service_start(tb_task *t, void *(*run)(void *), void *arg) { tb_task_start(t, run, arg); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6602; }
    { const char * tb_v6603 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v6603; }
    { const char * tb_v6604 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6604; }
    { const char * tb_v6605 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6605; }
    { const char * tb_v6606 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v6606; }
    { const char * tb_v6607 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6607; }
    { const char * tb_v6608 = "// a.crashed: в обычной программе падение задачи роняет всю программу — сюда доходят только целые\n"; *(const char * *)tb_grow(v_lines) = tb_v6608; }
    { const char * tb_v6609 = "TB_API _Bool tb_crashed(tb_task *t) { tb_wait(t); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6609; }
    { const char * tb_v6610 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6610; }
    { const char * tb_v6611 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6611; }
    { const char * tb_v6612 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6612; }
    { const char * tb_v6613 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6613; }
    { const char * tb_v6614 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6614; }
    { const char * tb_v6615 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v6615; }
    { const char * tb_v6616 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6616; }
    { const char * tb_v6617 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v6617; }
    { const char * tb_v6618 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6618; }
    { const char * tb_v6619 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6619; }
    { const char * tb_v6620 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6620; }
    { const char * tb_v6621 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6621; }
