    { const char * tb_v6623 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6623; }
    { const char * tb_v6624 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6624; }
    { const char * tb_v6625 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v6625; }
    { const char * tb_v6626 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6626; }
    { const char * tb_v6627 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6627; }
    { const char * tb_v6628 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v6628; }
