    { const char * tb_v6767 = "typedef struct { uint64_t size, magic; } tb_memh;\n"; *(const char * *)tb_grow(v_lines) = tb_v6767; }
    { const char * tb_v6768 = "typedef struct { uintptr_t a; uint64_t n; int live, line, fline; } tb_memb;\n"; *(const char * *)tb_grow(v_lines) = tb_v6768; }
    { const char * tb_v6769 = "TB_API int tb_mem_check = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6769; }
    { const char * tb_v6770 = "TB_API tb_memb *tb_mem_all = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6770; }
    { const char * tb_v6771 = "TB_API long long tb_mem_n = 0, tb_mem_cap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6771; }
    { const char * tb_v6772 = "TB_API volatile int tb_mem_spin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6772; }
