    { const char * tb_v6789 = "    char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v6789; }
    { const char * tb_v6790 = "    if (at > 0) snprintf(buf, sizeof buf, \"%s (блок из new_mem в строке %d)\", what, at);\n"; *(const char * *)tb_grow(v_lines) = tb_v6790; }
    { const char * tb_v6791 = "    else snprintf(buf, sizeof buf, \"%s\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v6791; }
    { const char * tb_v6792 = "    tb_mem_check = 0;   // программа падает: отчёт о неосвобождённом не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v6792; }
    { const char * tb_v6793 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v6793; }
