    { const char * tb_v6795 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6795; }
    { const char * tb_v6796 = "TB_API void tb_mem_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6796; }
    { const char * tb_v6797 = "    long long n = 0, bytes = 0; int first = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6797; }
    { const char * tb_v6798 = "    for (long long i = 0; i < tb_mem_n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6798; }
    { const char * tb_v6799 = "        if (tb_mem_all[i].live) { if (!n) first = tb_mem_all[i].line; n++; bytes += (long long)tb_mem_all[i].n; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6799; }
    { const char * tb_v6800 = "    if (n && tb_mem_check) fprintf(stderr, tb_tr(\"TB_MEM_CHECK: не освобождено блоков %lld (%lld байт), первый из new_mem в строке %d\\n\"), n, bytes, first);\n"; *(const char * *)tb_grow(v_lines) = tb_v6800; }
    { const char * tb_v6801 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6801; }
    { const char * tb_v6802 = "// TB_MEM_CHECK: можно ли трогать байты [a, a + n)\n"; *(const char * *)tb_grow(v_lines) = tb_v6802; }
    { const char * tb_v6803 = "static void tb_mem_touch(uintptr_t a, uint64_t n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6803; }
    { const char * tb_v6804 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6804; }
    { const char * tb_v6805 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v6805; }
    { const char * tb_v6806 = "    for (long long i = 0; i < tb_mem_n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6806; }
    { const char * tb_v6807 = "        tb_memb *b = &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6807; }
    { const char * tb_v6808 = "        uintptr_t lo = b->a - sizeof(tb_memh), hi = b->a + b->n + TB_MEM_GUARD;\n"; *(const char * *)tb_grow(v_lines) = tb_v6808; }
    { const char * tb_v6809 = "        if (a + n <= lo || a >= hi) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v6809; }
    { const char * tb_v6810 = "        if (!b->live) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6810; }
    { const char * tb_v6811 = "            char buf[400];\n"; *(const char * *)tb_grow(v_lines) = tb_v6811; }
    { const char * tb_v6812 = "            snprintf(buf, sizeof buf, \"эта память уже освобождена: free_mem в строке %d\", b->fline);\n"; *(const char * *)tb_grow(v_lines) = tb_v6812; }
    { const char * tb_v6813 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v6813; }
    { const char * tb_v6814 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6814; }
    { const char * tb_v6815 = "        if (a < b->a || a + n > b->a + b->n) tb_mem_die(line, \"чтение или запись за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v6815; }
    { const char * tb_v6816 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6816; }
    { const char * tb_v6817 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v6817; }
    { const char * tb_v6818 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6818; }
    { const char * tb_v6819 = "static tb_memb *tb_mem_find(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6819; }
    { const char * tb_v6820 = "    for (long long i = tb_mem_n - 1; i >= 0; i--) if (tb_mem_all[i].a == a) return &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6820; }
    { const char * tb_v6821 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6821; }
    { const char * tb_v6822 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6822; }
    { const char * tb_v6823 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v6823; }
    { const char * tb_v6824 = "#define TB_TOUCH(a, n) if (TB_RARE(tb_memchk())) tb_mem_touch((uintptr_t)(a), (n), line)\n"; *(const char * *)tb_grow(v_lines) = tb_v6824; }
    { const char * tb_v6825 = "TB_INL long long tb_rd8(long long a, int line) { TB_TOUCH(a, 1); return *(volatile uint8_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6825; }
    { const char * tb_v6826 = "TB_INL long long tb_rd16(long long a, int line) { TB_TOUCH(a, 2); return *(volatile uint16_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6826; }
