    { const char * tb_v6920 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6920; }
    { const char * tb_v6921 = "    tb_memh *q = realloc(h, sizeof(tb_memh) + (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6921; }
    { const char * tb_v6922 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6922; }
