    { const char * tb_v6938 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v6938; }
    { const char * tb_v6939 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v6939; }
    { const char * tb_v6940 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v6940; }
    { const char * tb_v6941 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v6941; }
