    { const char * tb_v6943 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6943; }
    { const char * tb_v6944 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v6944; }
    { const char * tb_v6945 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6945; }
    { const char * tb_v6946 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v6946; }
    { const char * tb_v6947 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v6947; }
    { const char * tb_v6948 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6948; }
