    { const char * tb_v7176 = "// ---------- канал: очередь между потоками (channel int / text ...) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7176; }
    { const char * tb_v7177 = "// send кладёт в конец (очередь растёт, отправитель не ждёт), receive берёт из начала\n"; *(const char * *)tb_grow(v_lines) = tb_v7177; }
