    { const char * tb_v7484 = "    else if (u < 0x800) { o[0] = (char)(0xC0 | (u >> 6)); o[1] = (char)(0x80 | (u & 63)); tb_ntyped += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7484; }
    { const char * tb_v7485 = "    else if (u < 0x10000) { o[0] = (char)(0xE0 | (u >> 12)); o[1] = (char)(0x80 | ((u >> 6) & 63)); o[2] = (char)(0x80 | (u & 63)); tb_ntyped += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7485; }
    { const char * tb_v7486 = "    else { o[0] = (char)(0xF0 | (u >> 18)); o[1] = (char)(0x80 | ((u >> 12) & 63)); o[2] = (char)(0x80 | ((u >> 6) & 63)); o[3] = (char)(0x80 | (u & 63)); tb_ntyped += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7486; }
    { const char * tb_v7487 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7487; }
    { const char * tb_v7488 = "TB_API void tb_type_utf8(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7488; }
    { const char * tb_v7489 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7489; }
    { const char * tb_v7490 = "    while (p && *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7490; }
    { const char * tb_v7491 = "        unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7491; }
    { const char * tb_v7492 = "        if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7492; }
    { const char * tb_v7493 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7493; }
    { const char * tb_v7494 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v7494; }
    { const char * tb_v7495 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v7495; }
    { const char * tb_v7496 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7496; }
