    { const char * tb_v7498 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7498; }
    { const char * tb_v7499 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7499; }
    { const char * tb_v7500 = "TB_API unsigned char tb_keys[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v7500; }
    { const char * tb_v7501 = "TB_API unsigned char tb_ktap[256];   // клавишу нажали и отпустили между кадрами: key_down() разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v7501; }
    { const char * tb_v7502 = "TB_API long long tb_last_frame = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7502; }
    { const char * tb_v7503 = "// клавиши: буквы и цифры — свой код ASCII (A..Z, 0..9), остальные:\n"; *(const char * *)tb_grow(v_lines) = tb_v7503; }
    { const char * tb_v7504 = "enum { TB_K_ENTER = 10, TB_K_ESC = 27, TB_K_SPACE = 32, TB_K_BACK = 8, TB_K_TAB = 9,\n"; *(const char * *)tb_grow(v_lines) = tb_v7504; }
