    { const char * tb_v7507 = "       TB_K_PGDN = 11, TB_K_F1 = 128 };   // F1..F12 — 128..139\n"; *(const char * *)tb_grow(v_lines) = tb_v7507; }
    { const char * tb_v7508 = "// ---------- картинки PNG (load_image; JPEG, BMP, GIF — ниже) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7508; }
    { const char * tb_v7509 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v7509; }
    { const char * tb_v7510 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v7510; }
    { const char * tb_v7511 = "typedef struct { const unsigned char *p, *end; unsigned bits; int nb, err; unsigned char *out; size_t n, cap; } tb_zs;\n"; *(const char * *)tb_grow(v_lines) = tb_v7511; }
    { const char * tb_v7512 = "typedef struct { short count[16], sym[320]; } tb_huff;\n"; *(const char * *)tb_grow(v_lines) = tb_v7512; }
    { const char * tb_v7513 = "TB_API unsigned tb_zbits(tb_zs *z, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7513; }
    { const char * tb_v7514 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7514; }
    { const char * tb_v7515 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7515; }
    { const char * tb_v7516 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v7516; }
    { const char * tb_v7517 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7517; }
    { const char * tb_v7518 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7518; }
    { const char * tb_v7519 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7519; }
    { const char * tb_v7520 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7520; }
    { const char * tb_v7521 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7521; }
    { const char * tb_v7522 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7522; }
    { const char * tb_v7523 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7523; }
    { const char * tb_v7524 = "        size_t nc = z->cap ? z->cap * 2 : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v7524; }
    { const char * tb_v7525 = "        unsigned char *q = realloc(z->out, nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7525; }
    { const char * tb_v7526 = "        if (!q) { z->err = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7526; }
    { const char * tb_v7527 = "        z->out = q; z->cap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7527; }
    { const char * tb_v7528 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7528; }
    { const char * tb_v7529 = "    z->out[z->n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7529; }
    { const char * tb_v7530 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7530; }
    { const char * tb_v7531 = "TB_API void tb_hbuild(tb_huff *h, const unsigned char *len, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7531; }
    { const char * tb_v7532 = "    short offs[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v7532; }
    { const char * tb_v7533 = "    memset(h->count, 0, sizeof h->count);\n"; *(const char * *)tb_grow(v_lines) = tb_v7533; }
    { const char * tb_v7534 = "    for (int i = 0; i < n; i++) h->count[len[i]]++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7534; }
    { const char * tb_v7535 = "    h->count[0] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7535; }
    { const char * tb_v7536 = "    offs[1] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7536; }
    { const char * tb_v7537 = "    for (int l = 1; l < 15; l++) offs[l + 1] = offs[l] + h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v7537; }
    { const char * tb_v7538 = "    for (int i = 0; i < n; i++) if (len[i]) h->sym[offs[len[i]]++] = (short)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v7538; }
    { const char * tb_v7539 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7539; }
    { const char * tb_v7540 = "TB_API int tb_hdec(tb_zs *z, const tb_huff *h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7540; }
    { const char * tb_v7541 = "    int code = 0, first = 0, index = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7541; }
    { const char * tb_v7542 = "    for (int l = 1; l < 16; l++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7542; }
    { const char * tb_v7543 = "        code |= (int)tb_zbits(z, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7543; }
    { const char * tb_v7544 = "        int c = h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v7544; }
