    { const char * tb_v8192 = "// image_scaled(картинка, w, h): новая картинка другого размера (уменьшение — среднее по площади,\n"; *(const char * *)tb_grow(v_lines) = tb_v8192; }
    { const char * tb_v8193 = "// увеличение — ближайшая точка). Так фото с диска влезает в окно, значок — в свой квадрат.\n"; *(const char * *)tb_grow(v_lines) = tb_v8193; }
    { const char * tb_v8194 = "TB_API long long tb_image_scaled(long long i, long long w, long long h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8194; }
    { const char * tb_v8195 = "    if (i < 0 || i >= tb_nimg) { tb_err = \"нет такой картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8195; }
    { const char * tb_v8196 = "    if (w < 1 || h < 1 || w * h > (1ll << 26)) { tb_err = \"такой размер не годится\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8196; }
    { const char * tb_v8197 = "    int sw = tb_imgs[i].w, sh = tb_imgs[i].h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8197; }
    { const char * tb_v8198 = "    size_t need = tb_imgpx_n + (size_t)w * h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8198; }
    { const char * tb_v8199 = "    if (need > 0xFFFFFFFFu) { tb_err = \"слишком много картинок\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8199; }
    { const char * tb_v8200 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8200; }
    { const char * tb_v8201 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v8201; }
    { const char * tb_v8202 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v8202; }
    { const char * tb_v8203 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v8203; }
    { const char * tb_v8204 = "    if (!all || !list) { tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8204; }
    { const char * tb_v8205 = "    const uint32_t *src = tb_imgpx + tb_imgs[i].off;\n"; *(const char * *)tb_grow(v_lines) = tb_v8205; }
    { const char * tb_v8206 = "    uint32_t *dst = tb_imgpx + tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8206; }
    { const char * tb_v8207 = "    for (long long y = 0; y < h; y++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8207; }
    { const char * tb_v8208 = "        int y0 = (int)(y * sh / h), y1 = (int)((y + 1) * sh / h);\n"; *(const char * *)tb_grow(v_lines) = tb_v8208; }
    { const char * tb_v8209 = "        if (y1 <= y0) y1 = y0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8209; }
    { const char * tb_v8210 = "        for (long long x = 0; x < w; x++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8210; }
    { const char * tb_v8211 = "            int x0 = (int)(x * sw / w), x1 = (int)((x + 1) * sw / w);\n"; *(const char * *)tb_grow(v_lines) = tb_v8211; }
    { const char * tb_v8212 = "            if (x1 <= x0) x1 = x0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8212; }
    { const char * tb_v8213 = "            unsigned long long a = 0, r = 0, g = 0, b = 0, n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8213; }
    { const char * tb_v8214 = "            for (int yy = y0; yy < y1; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8214; }
    { const char * tb_v8215 = "                for (int xx = x0; xx < x1; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8215; }
    { const char * tb_v8216 = "                    uint32_t c = src[(size_t)yy * sw + xx];\n"; *(const char * *)tb_grow(v_lines) = tb_v8216; }
    { const char * tb_v8217 = "                    a += c >> 24; r += c >> 16 & 255; g += c >> 8 & 255; b += c & 255; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8217; }
    { const char * tb_v8218 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v8218; }
    { const char * tb_v8219 = "            dst[(size_t)y * w + x] = (uint32_t)(a / n) << 24 | (uint32_t)(r / n) << 16 | (uint32_t)(g / n) << 8 | (uint32_t)(b / n);\n"; *(const char * *)tb_grow(v_lines) = tb_v8219; }
    { const char * tb_v8220 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8220; }
