    { const char * tb_v8237 = "    for (size_t i = 0; i < n; i++) tb_imgpx[tb_imgpx_n + i] = tb_px[i] | 0xFF000000u;\n"; *(const char * *)tb_grow(v_lines) = tb_v8237; }
    { const char * tb_v8238 = "    tb_imgs[tb_nimg].w = tb_gw; tb_imgs[tb_nimg].h = tb_gh; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8238; }
    { const char * tb_v8239 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v8239; }
