    { const char * tb_v8542 = "            int ai = a >= 1 ? 255 : (int)(a * 255 + 0.5f);\n"; *(const char * *)tb_grow(v_lines) = tb_v8542; }
    { const char * tb_v8543 = "            px[j * w + i] = ((uint32_t)ai << 24) | (color & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v8543; }
    { const char * tb_v8544 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8544; }
    { const char * tb_v8545 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8545; }
    { const char * tb_v8546 = "    free(acc);\n"; *(const char * *)tb_grow(v_lines) = tb_v8546; }
    { const char * tb_v8547 = "    tb_imgs[tb_nimg].w = w; tb_imgs[tb_nimg].h = h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8547; }
    { const char * tb_v8548 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v8548; }
    { const char * tb_v8549 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8549; }
    { const char * tb_v8550 = "    c->img = tb_nimg++; c->left = left; c->top = top;\n"; *(const char * *)tb_grow(v_lines) = tb_v8550; }
    { const char * tb_v8551 = "    return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8551; }
    { const char * tb_v8552 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8552; }
    { const char * tb_v8553 = "// высота строки — size * 5 / 4; линия букв — так, чтобы верх и низ шрифта легли в эту строку\n"; *(const char * *)tb_grow(v_lines) = tb_v8553; }
    { const char * tb_v8554 = "static int tb_font_base(const tb_font_t *f, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8554; }
    { const char * tb_v8555 = "    double lh = size * 5 / 4.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8555; }
    { const char * tb_v8556 = "    return (int)floor(lh * f->asc / (f->asc - f->desc) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8556; }
    { const char * tb_v8557 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8557; }
    { const char * tb_v8558 = "static unsigned tb_utf8_next(const unsigned char **pp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8558; }
    { const char * tb_v8559 = "    const unsigned char *p = *pp;\n"; *(const char * *)tb_grow(v_lines) = tb_v8559; }
    { const char * tb_v8560 = "    unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8560; }
    { const char * tb_v8561 = "    if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8561; }
    { const char * tb_v8562 = "        int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8562; }
    { const char * tb_v8563 = "        u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v8563; }
    { const char * tb_v8564 = "        while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v8564; }
    { const char * tb_v8565 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8565; }
    { const char * tb_v8566 = "    *pp = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v8566; }
    { const char * tb_v8567 = "    return u;\n"; *(const char * *)tb_grow(v_lines) = tb_v8567; }
    { const char * tb_v8568 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8568; }
    { const char * tb_v8569 = "TB_API long long tb_text_width(long long fi, const char *s, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8569; }
    { const char * tb_v8570 = "    if (fi < 0 || fi >= tb_nfonts || size <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8570; }
    { const char * tb_v8571 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v8571; }
    { const char * tb_v8572 = "    double scale = (double)size / f->upem, pen = 0, best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8572; }
    { const char * tb_v8573 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v8573; }
    { const char * tb_v8574 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8574; }
    { const char * tb_v8575 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v8575; }
    { const char * tb_v8576 = "        if (u == '\\n') { if (pen > best) best = pen; pen = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8576; }
    { const char * tb_v8577 = "        pen += tb_ttf_adv(f, tb_ttf_glyph(f, u)) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v8577; }
    { const char * tb_v8578 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8578; }
    { const char * tb_v8579 = "    if (pen > best) best = pen;\n"; *(const char * *)tb_grow(v_lines) = tb_v8579; }
    { const char * tb_v8580 = "    return (long long)floor(best + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8580; }
    { const char * tb_v8581 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8581; }
    { const char * tb_v8582 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v8582; }
    { const char * tb_v8583 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8583; }
    { const char * tb_v8584 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8584; }
    { const char * tb_v8585 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v8585; }
    { const char * tb_v8586 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8586; }
    { const char * tb_v8587 = "    long long base = y + tb_font_base(f, size), lh = size * 5 / 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v8587; }
    { const char * tb_v8588 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v8588; }
    { const char * tb_v8589 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8589; }
    { const char * tb_v8590 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v8590; }
    { const char * tb_v8591 = "        if (u == '\\n') { pen = 0; base += lh; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8591; }
    { const char * tb_v8592 = "        unsigned g = tb_ttf_glyph(f, u);\n"; *(const char * *)tb_grow(v_lines) = tb_v8592; }
    { const char * tb_v8593 = "        long long gx = x + (long long)floor(pen + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8593; }
    { const char * tb_v8594 = "        pen += tb_ttf_adv(f, g) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v8594; }
    { const char * tb_v8595 = "        if (u == ' ' || gx >= tb_gw || base - 2 * size > tb_gh) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8595; }
    { const char * tb_v8596 = "        tb_gcache *gc = tb_glyph_img((int)fi, g, (int)size, (uint32_t)c & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v8596; }
    { const char * tb_v8597 = "        if (gc->img >= 0) tb_draw_image_a(gc->img, gx + gc->left, base + gc->top);\n"; *(const char * *)tb_grow(v_lines) = tb_v8597; }
    { const char * tb_v8598 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8598; }
    { const char * tb_v8599 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8599; }
    { const char * tb_v8600 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v8600; }
    { const char * tb_v8601 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v8601; }
    { const char * tb_v8602 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v8602; }
    { const char * tb_v8603 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v8603; }
    { const char * tb_v8604 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v8604; }
    { const char * tb_v8605 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v8605; }
    { const char * tb_v8606 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v8606; }
    { const char * tb_v8607 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v8607; }
    { const char * tb_v8608 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v8608; }
    { const char * tb_v8609 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8609; }
    { const char * tb_v8610 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8610; }
    { const char * tb_v8611 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v8611; }
    { const char * tb_v8612 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8612; }
    { const char * tb_v8613 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v8613; }
    { const char * tb_v8614 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v8614; }
    { const char * tb_v8615 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8615; }
    { const char * tb_v8616 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8616; }
    { const char * tb_v8617 = "// 3D с картинкой (mesh_image): у треугольника ещё запись текстуры — плоскости u·W и v·W (по 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v8617; }
    { const char * tb_v8618 = "// и сама картинка; номер записи — в pad его плоскости глубины, а в m ещё бит 29\n"; *(const char * *)tb_grow(v_lines) = tb_v8618; }
    { const char * tb_v8619 = "typedef struct { int64_t au, bu, cu, av, bv, cv; uint32_t off, w, h, pad; } tb_gtex_t;   // 64 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v8619; }
    { const char * tb_v8620 = "enum { TB_GT_CAP = 16384 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8620; }
    { const char * tb_v8621 = "TB_API tb_gtex_t *tb_gtex = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8621; }
    { const char * tb_v8622 = "TB_API int tb_gtn = 0, tb_gpu_tex = 0;   // записей в текущем наборе; видеокарта умеет картинки на сетках\n"; *(const char * *)tb_grow(v_lines) = tb_v8622; }
    { const char * tb_v8623 = "// «новые» треугольники 3D (свет по углам, тени, туман, прозрачность — см. tb_lit_px): у каждого запись — W трёх углов,\n"; *(const char * *)tb_grow(v_lines) = tb_v8623; }
    { const char * tb_v8624 = "// флаги (1 — тени, 2 — туман, прозрачность << 8), по 12 чисел на угол (значение × W), туман, картинка, карта теней.\n"; *(const char * *)tb_grow(v_lines) = tb_v8624; }
    { const char * tb_v8625 = "// Номер записи — в pad плоскости глубины, а в m — бит 28 (и бит 27 у прозрачного)\n"; *(const char * *)tb_grow(v_lines) = tb_v8625; }
    { const char * tb_v8626 = "typedef struct { int32_t w[3], flags; int32_t v[3][12]; int32_t fogc, fogn, fogf, tex, smn, smbase, pad0, pad1; } tb_glit_t;   // 192 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v8626; }
    { const char * tb_v8627 = "enum { TB_GL_CAP = 16384, TB_LV = 11, TB_SM_N = 1024 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8627; }
    { const char * tb_v8628 = "TB_API tb_glit_t *tb_glit = 0;           // записи всех наборов (видны видеокарте; появляются при первом таком треугольнике)\n"; *(const char * *)tb_grow(v_lines) = tb_v8628; }
    { const char * tb_v8629 = "TB_API int tb_gln = 0, tb_gpu_lit = 0;   // записей в текущем наборе; видеокарта умеет такие треугольники\n"; *(const char * *)tb_grow(v_lines) = tb_v8629; }
    { const char * tb_v8630 = "TB_API void tb_gpu_lit_mem(int shadow);  // своя у каждой системы: память записей (0) или карт теней (1)\n"; *(const char * *)tb_grow(v_lines) = tb_v8630; }
    { const char * tb_v8631 = "TB_API void tb_gpu_tril(const long long *t, long long c, const uint32_t *pl, const tb_glit_t *L, const tb_gtex_t *tx);\n"; *(const char * *)tb_grow(v_lines) = tb_v8631; }
    { const char * tb_v8632 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v8632; }
    { const char * tb_v8633 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v8633; }
    { const char * tb_v8634 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v8634; }
    { const char * tb_v8635 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8635; }
    { const char * tb_v8636 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v8636; }
    { const char * tb_v8637 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v8637; }
    { const char * tb_v8638 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v8638; }
    { const char * tb_v8639 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v8639; }
    { const char * tb_v8640 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v8640; }
    { const char * tb_v8641 = "typedef struct { int32_t r[16]; } tb_grec;   // 4 строки: поворот × 2^30 и сдвиг × 4096 (3), свет в сетке (x, y, z × 2^14, фон × 256; фон -1 — без света)\n"; *(const char * *)tb_grow(v_lines) = tb_v8641; }
    { const char * tb_v8642 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8642; }
    { const char * tb_v8643 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v8643; }
    { const char * tb_v8644 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v8644; }
    { const char * tb_v8645 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v8645; }
    { const char * tb_v8646 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v8646; }
    { const char * tb_v8647 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v8647; }
    { const char * tb_v8648 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v8648; }
    { const char * tb_v8649 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v8649; }
    { const char * tb_v8650 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v8650; }
    { const char * tb_v8651 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v8651; }
    { const char * tb_v8652 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8652; }
    { const char * tb_v8653 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8653; }
    { const char * tb_v8654 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v8654; }
    { const char * tb_v8655 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0, tb_gpu_shskip = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8655; }
    { const char * tb_v8656 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v8656; }
    { const char * tb_v8657 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v8657; }
    { const char * tb_v8658 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8658; }
    { const char * tb_v8659 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v8659; }
    { const char * tb_v8660 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v8660; }
    { const char * tb_v8661 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8661; }
    { const char * tb_v8662 = "// несколько окон (1.3): номер текущего окна, сколько мест занято, ручка каждого окна в системе\n"; *(const char * *)tb_grow(v_lines) = tb_v8662; }
    { const char * tb_v8663 = "#define TB_WMAX 16\n"; *(const char * *)tb_grow(v_lines) = tb_v8663; }
    { const char * tb_v8664 = "TB_API int tb_wcur = 0, tb_wn = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8664; }
