    { const char * tb_v8795 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8795; }
    { const char * tb_v8796 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8796; }
    { const char * tb_v8797 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8797; }
    { const char * tb_v8798 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8798; }
    { const char * tb_v8799 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8799; }
    { const char * tb_v8800 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8800; }
