    { const char * tb_v8805 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8805; }
    { const char * tb_v8806 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8806; }
    { const char * tb_v8807 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8807; }
    { const char * tb_v8808 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8808; }
    { const char * tb_v8809 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8809; }
    { const char * tb_v8810 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8810; }
    { const char * tb_v8811 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8811; }
    { const char * tb_v8812 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8812; }
    { const char * tb_v8813 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8813; }
    { const char * tb_v8814 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v8814; }
    { const char * tb_v8815 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v8815; }
    { const char * tb_v8816 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8816; }
    { const char * tb_v8817 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v8817; }
    { const char * tb_v8818 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v8818; }
    { const char * tb_v8819 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8819; }
    { const char * tb_v8820 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8820; }
    { const char * tb_v8821 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8821; }
    { const char * tb_v8822 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8822; }
    { const char * tb_v8823 = "TB_API void tb_gpu_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8823; }
    { const char * tb_v8824 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v8824; }
    { const char * tb_v8825 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8825; }
    { const char * tb_v8826 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v8826; }
    { const char * tb_v8827 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8827; }
    { const char * tb_v8828 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v8828; }
    { const char * tb_v8829 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8829; }
    { const char * tb_v8830 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v8830; }
    { const char * tb_v8831 = "TB_API void tb_gpu_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8831; }
