    { const char * tb_v8864 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8864; }
    { const char * tb_v8865 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8865; }
