    { const char * tb_v11825 = "// --- клавиши для key_down / typed_text (набор 1, как шлёт контроллер клавиатуры) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v11825; }
    { const char * tb_v11826 = "TB_API int tb_kext = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11826; }
