    { const char * tb_v11847 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11847; }
    { const char * tb_v11848 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11848; }
    { const char * tb_v11849 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11849; }
    { const char * tb_v11850 = "TB_API void tb_gfx_key(unsigned char sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11850; }
    { const char * tb_v11851 = "    if (sc == 0xE0) { tb_kext = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11851; }
