    { const char * tb_v13434 = "    case XK_Alt_L: case XK_Alt_R: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v13434; }
    { const char * tb_v13435 = "    case XK_Delete: return TB_K_DEL; case XK_Home: return TB_K_HOME; case XK_End: return TB_K_END;\n"; *(const char * *)tb_grow(v_lines) = tb_v13435; }
    { const char * tb_v13436 = "    case XK_Prior: return TB_K_PGUP; case XK_Next: return TB_K_PGDN;\n"; *(const char * *)tb_grow(v_lines) = tb_v13436; }
    { const char * tb_v13437 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13437; }
