    { const char * tb_v13580 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v13580; }
