    { const char * tb_v13627 = "    memcpy(s->typed, tb_typed, sizeof s->typed); memcpy(s->keys, tb_keys, sizeof s->keys); memcpy(s->ktap, tb_ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v13627; }
