    { const char * tb_v13658 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13658; }
