    { const char * tb_v13738 = "// после событий: закрытые пользователем окна убрать, у остальных — новый кадр и новый размер\n"; *(const char * *)tb_grow(v_lines) = tb_v13738; }
    { const char * tb_v13739 = "static void tb_windows_after(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13739; }
