    { const char * tb_v13768 = "    tb_px = calloc((size_t)tb_gw * tb_gh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v13768; }
    { const char * tb_v13769 = "    if (!tb_gfx_open(title)) { free(tb_px); tb_px = 0; tb_err = \"не могу открыть окно: нет экрана\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13769; }
    { const char * tb_v13770 = "    tb_wn = 1; tb_wcur = 0; tb_wins[0].used = 1; tb_whand[0] = tb_gfx_handle();\n"; *(const char * *)tb_grow(v_lines) = tb_v13770; }
    { const char * tb_v13771 = "    if (tb_gpu_on && tb_gpu_check) { atexit(tb_gpu_report); tb_gpu_blend_probe(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13771; }
