    { const char * tb_v13773 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13773; }
    { const char * tb_v13774 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v13774; }
    { const char * tb_v13775 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v13775; }
    { const char * tb_v13776 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13776; }
    { const char * tb_v13777 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13777; }
    { const char * tb_v13778 = "    int nw = tb_new_w > 8192 ? 8192 : tb_new_w, nh = tb_new_h > 8192 ? 8192 : tb_new_h, ow = tb_gw, oh = tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v13778; }
    { const char * tb_v13779 = "    tb_new_w = tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13779; }
    { const char * tb_v13780 = "    if (nw < 1 || nh < 1 || (nw == ow && nh == oh)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13780; }
    { const char * tb_v13781 = "    uint32_t *np = calloc((size_t)nw * nh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v13781; }
    { const char * tb_v13782 = "    if (!np) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13782; }
    { const char * tb_v13783 = "    for (int y = 0; y < oh && y < nh; y++) memcpy(np + (size_t)y * nw, tb_px + (size_t)y * ow, (size_t)(ow < nw ? ow : nw) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v13783; }
    { const char * tb_v13784 = "    free(tb_px);\n"; *(const char * *)tb_grow(v_lines) = tb_v13784; }
