    { const char * tb_v13786 = "    tb_gfx_reimage();\n"; *(const char * *)tb_grow(v_lines) = tb_v13786; }
    { const char * tb_v13787 = "    if (tb_gpu_on && !tb_gpu_resize(ow, oh)) fprintf(stderr, tb_tr(\"видеокарта: не получилось поменять размер кадра\\n\"));\n"; *(const char * *)tb_grow(v_lines) = tb_v13787; }
    { const char * tb_v13788 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13788; }
    { const char * tb_v13789 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13789; }
    { const char * tb_v13790 = "TB_API long long tb_window_h(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gh; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13790; }
    { const char * tb_v13791 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v13791; }
    { const char * tb_v13792 = "TB_API double tb_frame_ms_v = 16.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13792; }
    { const char * tb_v13793 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13793; }
    { const char * tb_v13794 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13794; }
    { const char * tb_v13795 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13795; }
    { const char * tb_v13796 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13796; }
    { const char * tb_v13797 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13797; }
    { const char * tb_v13798 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13798; }
    { const char * tb_v13799 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13799; }
    { const char * tb_v13800 = "TB_API double tb_frame_ms(void) { return tb_frame_ms_v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13800; }
    { const char * tb_v13801 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13801; }
    { const char * tb_v13802 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v13802; }
    { const char * tb_v13803 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13803; }
    { const char * tb_v13804 = "    if (tb_wn > 1) tb_windows_show();\n"; *(const char * *)tb_grow(v_lines) = tb_v13804; }
    { const char * tb_v13805 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13805; }
    { const char * tb_v13806 = "    TB_SCENE();        // сцена 3D, которая ждала (тени, прозрачные) — в этот кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v13806; }
    { const char * tb_v13807 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v13807; }
    { const char * tb_v13808 = "    if (tb_wn > 1) tb_windows_after();\n"; *(const char * *)tb_grow(v_lines) = tb_v13808; }
    { const char * tb_v13809 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v13809; }
    { const char * tb_v13810 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v13810; }
    { const char * tb_v13811 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v13811; }
    { const char * tb_v13812 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13812; }
    { const char * tb_v13813 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13813; }
    { const char * tb_v13814 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13814; }
    { const char * tb_v13815 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v13815; }
    { const char * tb_v13816 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13816; }
    { const char * tb_v13817 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v13817; }
    { const char * tb_v13818 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v13818; }
    { const char * tb_v13819 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v13819; }
    { const char * tb_v13820 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v13820; }
    { const char * tb_v13821 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13821; }
    { const char * tb_v13822 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13822; }
    { const char * tb_v13823 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v13823; }
    { const char * tb_v13824 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v13824; }
    { const char * tb_v13825 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v13825; }
    { const char * tb_v13826 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13826; }
    { const char * tb_v13827 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v13827; }
    { const char * tb_v13828 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v13828; }
    { const char * tb_v13829 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13829; }
    { const char * tb_v13830 = "TB_INL void tb_put(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13830; }
    { const char * tb_v13831 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13831; }
    { const char * tb_v13832 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13832; }
    { const char * tb_v13833 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v13833; }
    { const char * tb_v13834 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v13834; }
    { const char * tb_v13835 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v13835; }
    { const char * tb_v13836 = "TB_API long long tb_mdrawn = 0, tb_mdrawn_last = 0;   // сколько draw_mesh дошло до рисования (не отсечено) в кадре\n"; *(const char * *)tb_grow(v_lines) = tb_v13836; }
    { const char * tb_v13837 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13837; }
    { const char * tb_v13838 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13838; }
    { const char * tb_v13839 = "    tb_mdrawn_last = tb_mdrawn; tb_mdrawn = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13839; }
    { const char * tb_v13840 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13840; }
    { const char * tb_v13841 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v13841; }
    { const char * tb_v13842 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13842; }
    { const char * tb_v13843 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13843; }
    { const char * tb_v13844 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13844; }
    { const char * tb_v13845 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13845; }
    { const char * tb_v13846 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13846; }
    { const char * tb_v13847 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13847; }
    { const char * tb_v13848 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13848; }
    { const char * tb_v13849 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13849; }
    { const char * tb_v13850 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v13850; }
    { const char * tb_v13851 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13851; }
