    { const char * tb_v13891 = "            if (a > 0) tb_gpu_rect(x - k, y - k + r, w + 2 * k, h + 2 * k - 2 * r, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v13891; }
    { const char * tb_v13892 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13892; }
