    { const char * tb_v13894 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13894; }
    { const char * tb_v13895 = "    double hw = w / 2.0, hh = h / 2.0, cx = x + hw, cy = y + hh;\n"; *(const char * *)tb_grow(v_lines) = tb_v13895; }
    { const char * tb_v13896 = "    long long y0 = y - size < 0 ? 0 : y - size, y1 = y + h + size > tb_gh ? tb_gh : y + h + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v13896; }
