    { const char * tb_v13923 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v13923; }
    { const char * tb_v13924 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v13924; }
    { const char * tb_v13925 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13925; }
    { const char * tb_v13926 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v13926; }
