    { const char * tb_v13987 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v13987; }
    { const char * tb_v13988 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v13988; }
    { const char * tb_v13989 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13989; }
    { const char * tb_v13990 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13990; }
    { const char * tb_v13991 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13991; }
    { const char * tb_v13992 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v13992; }
    { const char * tb_v13993 = "    long long W = x1 - x0, H = y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13993; }
    { const char * tb_v13994 = "    if (W <= 1 || H <= 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13994; }
    { const char * tb_v13995 = "    int half = r >= 4 && W >= 8 && H >= 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v13995; }
    { const char * tb_v13996 = "    long long bw = half ? (W + 1) / 2 : W, bh = half ? (H + 1) / 2 : H, br = half ? r / 2 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v13996; }
    { const char * tb_v13997 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v13997; }
    { const char * tb_v13998 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13998; }
    { const char * tb_v13999 = "    uint32_t *tmp = b + bw * bh;\n"; *(const char * *)tb_grow(v_lines) = tb_v13999; }
    { const char * tb_v14000 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v14000; }
    { const char * tb_v14001 = "        for (long long yy = 0; yy < bh; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14001; }
    { const char * tb_v14002 = "            for (long long xx = 0; xx < bw; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14002; }
    { const char * tb_v14003 = "                long long sx = x0 + xx * 2, sy = y0 + yy * 2, sx2 = sx + 1 < x1 ? sx + 1 : sx, sy2 = sy + 1 < y1 ? sy + 1 : sy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14003; }
    { const char * tb_v14004 = "                uint32_t p = tb_px[sy * tb_gw + sx], q = tb_px[sy * tb_gw + sx2], u = tb_px[sy2 * tb_gw + sx], v = tb_px[sy2 * tb_gw + sx2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14004; }
    { const char * tb_v14005 = "                b[yy * bw + xx] = (((p >> 16 & 255) + (q >> 16 & 255) + (u >> 16 & 255) + (v >> 16 & 255) + 2) / 4) << 16\n"; *(const char * *)tb_grow(v_lines) = tb_v14005; }
    { const char * tb_v14006 = "                    | (((p >> 8 & 255) + (q >> 8 & 255) + (u >> 8 & 255) + (v >> 8 & 255) + 2) / 4) << 8\n"; *(const char * *)tb_grow(v_lines) = tb_v14006; }
    { const char * tb_v14007 = "                    | (((p & 255) + (q & 255) + (u & 255) + (v & 255) + 2) / 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14007; }
    { const char * tb_v14008 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14008; }
    { const char * tb_v14009 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v14009; }
    { const char * tb_v14010 = "        for (long long yy = 0; yy < bh; yy++) memcpy(b + yy * bw, tb_px + (y0 + yy) * tb_gw + x0, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14010; }
    { const char * tb_v14011 = "    for (int pass = 0; pass < 3; pass++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14011; }
    { const char * tb_v14012 = "        for (long long yy = 0; yy < bh; yy++) tb_blur_run(b + yy * bw, bw, 1, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v14012; }
    { const char * tb_v14013 = "        for (long long xx = 0; xx < bw; xx++) tb_blur_run(b + xx, bh, bw, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v14013; }
    { const char * tb_v14014 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14014; }
    { const char * tb_v14015 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v14015; }
    { const char * tb_v14016 = "        // обратно: каждая точка — смесь четырёх соседних из маленькой картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v14016; }
    { const char * tb_v14017 = "        for (long long yy = 0; yy < H; yy++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14017; }
    { const char * tb_v14018 = "            long long fy = yy * 128 - 64; if (fy < 0) fy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14018; }
    { const char * tb_v14019 = "            long long iy = fy >> 8, ty = fy & 255, iy2 = iy + 1 < bh ? iy + 1 : iy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14019; }
    { const char * tb_v14020 = "            for (long long xx = 0; xx < W; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14020; }
    { const char * tb_v14021 = "                long long fx = xx * 128 - 64; if (fx < 0) fx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14021; }
    { const char * tb_v14022 = "                long long ix = fx >> 8, tx = fx & 255, ix2 = ix + 1 < bw ? ix + 1 : ix;\n"; *(const char * *)tb_grow(v_lines) = tb_v14022; }
    { const char * tb_v14023 = "                uint32_t p = b[iy * bw + ix], q = b[iy * bw + ix2], u = b[iy2 * bw + ix], v = b[iy2 * bw + ix2], o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14023; }
    { const char * tb_v14024 = "                for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14024; }
    { const char * tb_v14025 = "                    long long a = (p >> sh & 255) * (256 - tx) + (q >> sh & 255) * tx, c = (u >> sh & 255) * (256 - tx) + (v >> sh & 255) * tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v14025; }
    { const char * tb_v14026 = "                    o |= (uint32_t)(((a * (256 - ty) + c * ty + 32768) >> 16) & 255) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v14026; }
    { const char * tb_v14027 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v14027; }
    { const char * tb_v14028 = "                tb_px[(y0 + yy) * tb_gw + x0 + xx] = o;\n"; *(const char * *)tb_grow(v_lines) = tb_v14028; }
    { const char * tb_v14029 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14029; }
    { const char * tb_v14030 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14030; }
    { const char * tb_v14031 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v14031; }
    { const char * tb_v14032 = "        for (long long yy = 0; yy < bh; yy++) memcpy(tb_px + (y0 + yy) * tb_gw + x0, b + yy * bw, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14032; }
    { const char * tb_v14033 = "    free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v14033; }
    { const char * tb_v14034 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14034; }
    { const char * tb_v14035 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14035; }
    { const char * tb_v14036 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14036; }
    { const char * tb_v14037 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14037; }
    { const char * tb_v14038 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14038; }
    { const char * tb_v14039 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v14039; }
    { const char * tb_v14040 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14040; }
    { const char * tb_v14041 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v14041; }
    { const char * tb_v14042 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14042; }
