    { const char * tb_v14044 = "                if ((c >> 24) & 255) { uint32_t *p = &tb_px[(cy + j) * tb_gw + cx + i]; *p = tb_mix(*p, (uint32_t)c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14044; }
    { const char * tb_v14045 = "                else tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14045; }
    { const char * tb_v14046 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14046; }
    { const char * tb_v14047 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14047; }
    { const char * tb_v14048 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14048; }
    { const char * tb_v14049 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14049; }
    { const char * tb_v14050 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14050; }
    { const char * tb_v14051 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14051; }
    { const char * tb_v14052 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14052; }
    { const char * tb_v14053 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14053; }
    { const char * tb_v14054 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v14054; }
    { const char * tb_v14055 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14055; }
    { const char * tb_v14056 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v14056; }
    { const char * tb_v14057 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14057; }
    { const char * tb_v14058 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v14058; }
    { const char * tb_v14059 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v14059; }
    { const char * tb_v14060 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14060; }
    { const char * tb_v14061 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14061; }
    { const char * tb_v14062 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14062; }
    { const char * tb_v14063 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14063; }
    { const char * tb_v14064 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v14064; }
    { const char * tb_v14065 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14065; }
    { const char * tb_v14066 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v14066; }
    { const char * tb_v14067 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v14067; }
    { const char * tb_v14068 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v14068; }
    { const char * tb_v14069 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v14069; }
    { const char * tb_v14070 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v14070; }
    { const char * tb_v14071 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14071; }
    { const char * tb_v14072 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v14072; }
    { const char * tb_v14073 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14073; }
    { const char * tb_v14074 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14074; }
    { const char * tb_v14075 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14075; }
    { const char * tb_v14076 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14076; }
    { const char * tb_v14077 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14077; }
    { const char * tb_v14078 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14078; }
    { const char * tb_v14079 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14079; }
    { const char * tb_v14080 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14080; }
    { const char * tb_v14081 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14081; }
    { const char * tb_v14082 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14082; }
    { const char * tb_v14083 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14083; }
    { const char * tb_v14084 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14084; }
    { const char * tb_v14085 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v14085; }
    { const char * tb_v14086 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14086; }
    { const char * tb_v14087 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14087; }
    { const char * tb_v14088 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v14088; }
    { const char * tb_v14089 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v14089; }
    { const char * tb_v14090 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14090; }
    { const char * tb_v14091 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v14091; }
    { const char * tb_v14092 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v14092; }
    { const char * tb_v14093 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14093; }
    { const char * tb_v14094 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14094; }
    { const char * tb_v14095 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v14095; }
    { const char * tb_v14096 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v14096; }
    { const char * tb_v14097 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14097; }
    { const char * tb_v14098 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v14098; }
    { const char * tb_v14099 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v14099; }
    { const char * tb_v14100 = "// треугольник с картинкой: tb_tex_cur — его запись текстуры (иначе 0). Точка картинки для (x, y):\n"; *(const char * *)tb_grow(v_lines) = tb_v14100; }
    { const char * tb_v14101 = "// W = (2^24 - глубина) >> 4 (это 1/z), u = (плоскость u·W) / W — с перспективой, как на видеокарте (tbt.frag)\n"; *(const char * *)tb_grow(v_lines) = tb_v14101; }
    { const char * tb_v14102 = "TB_API const tb_gtex_t *tb_tex_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14102; }
    { const char * tb_v14103 = "TB_INL long long tb_fdiv(long long a, long long b);\n"; *(const char * *)tb_grow(v_lines) = tb_v14103; }
    { const char * tb_v14104 = "TB_INL int tb_tex_px(const tb_gtex_t *tx, uint32_t d, long long x, long long y, uint32_t *out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14104; }
    { const char * tb_v14105 = "    long long W = (16777216 - (long long)d) >> 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v14105; }
    { const char * tb_v14106 = "    if (W < 1) W = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14106; }
    { const char * tb_v14107 = "    long long su = (tx->cu + tx->au * (2 * x + 1) + tx->bu * (2 * y + 1)) >> 6, sv = (tx->cv + tx->av * (2 * x + 1) + tx->bv * (2 * y + 1)) >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v14107; }
    { const char * tb_v14108 = "    long long u = tb_fdiv(tb_fdiv(su, W), 16), v = tb_fdiv(tb_fdiv(sv, W), 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v14108; }
    { const char * tb_v14109 = "    u -= tb_fdiv(u, tx->w) * (long long)tx->w;   // повтор картинки: 0…w-1\n"; *(const char * *)tb_grow(v_lines) = tb_v14109; }
