    { const char * tb_v14247 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14247; }
    { const char * tb_v14248 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14248; }
    { const char * tb_v14249 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14249; }
    { const char * tb_v14250 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14250; }
    { const char * tb_v14251 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14251; }
    { const char * tb_v14252 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v14252; }
    { const char * tb_v14253 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14253; }
    { const char * tb_v14254 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14254; }
    { const char * tb_v14255 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v14255; }
    { const char * tb_v14256 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14256; }
    { const char * tb_v14257 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v14257; }
    { const char * tb_v14258 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v14258; }
    { const char * tb_v14259 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14259; }
    { const char * tb_v14260 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v14260; }
    { const char * tb_v14261 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v14261; }
    { const char * tb_v14262 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v14262; }
    { const char * tb_v14263 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14263; }
    { const char * tb_v14264 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14264; }
    { const char * tb_v14265 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v14265; }
    { const char * tb_v14266 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v14266; }
    { const char * tb_v14267 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v14267; }
    { const char * tb_v14268 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v14268; }
    { const char * tb_v14269 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v14269; }
    { const char * tb_v14270 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v14270; }
    { const char * tb_v14271 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v14271; }
    { const char * tb_v14272 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14272; }
    { const char * tb_v14273 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v14273; }
    { const char * tb_v14274 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14274; }
    { const char * tb_v14275 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14275; }
    { const char * tb_v14276 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14276; }
    { const char * tb_v14277 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v14277; }
    { const char * tb_v14278 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14278; }
    { const char * tb_v14279 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14279; }
    { const char * tb_v14280 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v14280; }
    { const char * tb_v14281 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v14281; }
    { const char * tb_v14282 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v14282; }
    { const char * tb_v14283 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v14283; }
    { const char * tb_v14284 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v14284; }
    { const char * tb_v14285 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v14285; }
    { const char * tb_v14286 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v14286; }
    { const char * tb_v14287 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v14287; }
    { const char * tb_v14288 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v14288; }
    { const char * tb_v14289 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v14289; }
    { const char * tb_v14290 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v14290; }
    { const char * tb_v14291 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v14291; }
    { const char * tb_v14292 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v14292; }
    { const char * tb_v14293 = "typedef struct { int parent, useq; double piv[3], rot[3], mv[3], q[4]; } tb_bone_t;   // кость: родитель, сустав, поворот (или кватернион q, useq), сдвиг\n"; *(const char * *)tb_grow(v_lines) = tb_v14293; }
    { const char * tb_v14294 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v14294; }
    { const char * tb_v14295 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v14295; }
    { const char * tb_v14296 = "    int32_t *nrm; long long nrmcap; int nrmok;   // нормаль каждого треугольника в сетке (× 2^14), для света\n"; *(const char * *)tb_grow(v_lines) = tb_v14296; }
    { const char * tb_v14297 = "    double *uv; long long tex;   // картинка сетки (mesh_image, -1 — нет) и (u, v) трёх углов треугольника (NAN — без картинки)\n"; *(const char * *)tb_grow(v_lines) = tb_v14297; }
    { const char * tb_v14298 = "    long long nch, *chr; double *chs, bs[4]; int chok;\n"; *(const char * *)tb_grow(v_lines) = tb_v14298; }
    { const char * tb_v14299 = "    int smooth, alpha, cnok; double shine, glow; double *cn; long long cncap;   // плавный свет, прозрачность 0…255, блеск, свечение; нормали в углах\n"; *(const char * *)tb_grow(v_lines) = tb_v14299; }
    { const char * tb_v14300 = "    tb_bone_t *bones; long long nb, capb; int16_t *sb; float *sw;\n"; *(const char * *)tb_grow(v_lines) = tb_v14300; }
    { const char * tb_v14301 = "    int shp, shc, shok; float shv[16]; int shimg[4]; int noshadow; float *shvd; long long shvn, shvcap, shused; void *shvb;\n"; *(const char * *)tb_grow(v_lines) = tb_v14301; }
    { const char * tb_v14302 = "    long long lod; double lodd, far, ub[4]; int hasub; } tb_mesh;   // lod — сетка вместо этой дальше lodd; far — дальше не рисовать; ub — свой шар (mesh_bounds)   // gpu func: шейдер точки и углов (-1 — обычный), настройки, углы для видеокарты     // кости и у каждого угла до 4 костей с весами   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v14302; }
    { const char * tb_v14303 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14303; }
    { const char * tb_v14304 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14304; }
    { const char * tb_v14305 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v14305; }
    { const char * tb_v14306 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v14306; }
    { const char * tb_v14307 = "TB_API long long *tb_mfree = 0, tb_nmfree = 0, tb_capmfree = 0;   // номера сеток после mesh_free: mesh_new берёт их снова\n"; *(const char * *)tb_grow(v_lines) = tb_v14307; }
    { const char * tb_v14308 = "static void tb_mesh_reset(long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14308; }
    { const char * tb_v14309 = "    memset(&tb_meshes[i], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v14309; }
    { const char * tb_v14310 = "    tb_meshes[i].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14310; }
    { const char * tb_v14311 = "    tb_meshes[i].tex = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14311; }
    { const char * tb_v14312 = "    tb_meshes[i].alpha = 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14312; }
    { const char * tb_v14313 = "    tb_meshes[i].shp = tb_meshes[i].shc = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14313; }
    { const char * tb_v14314 = "    tb_meshes[i].shused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14314; }
    { const char * tb_v14315 = "    tb_meshes[i].lod = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14315; }
    { const char * tb_v14316 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14316; }
    { const char * tb_v14317 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14317; }
    { const char * tb_v14318 = "    if (tb_nmfree > 0) { long long i = tb_mfree[--tb_nmfree]; tb_mesh_reset(i); return i; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14318; }
    { const char * tb_v14319 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14319; }
    { const char * tb_v14320 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v14320; }
    { const char * tb_v14321 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v14321; }
    { const char * tb_v14322 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14322; }
    { const char * tb_v14323 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v14323; }
    { const char * tb_v14324 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14324; }
    { const char * tb_v14325 = "    tb_meshes[tb_nmesh].tex = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14325; }
    { const char * tb_v14326 = "    tb_meshes[tb_nmesh].alpha = 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14326; }
    { const char * tb_v14327 = "    tb_meshes[tb_nmesh].shp = tb_meshes[tb_nmesh].shc = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14327; }
    { const char * tb_v14328 = "    tb_meshes[tb_nmesh].shused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14328; }
    { const char * tb_v14329 = "    tb_meshes[tb_nmesh].lod = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14329; }
    { const char * tb_v14330 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14330; }
    { const char * tb_v14331 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14331; }
    { const char * tb_v14332 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14332; }
    { const char * tb_v14333 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14333; }
    { const char * tb_v14334 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v14334; }
    { const char * tb_v14335 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14335; }
    { const char * tb_v14336 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14336; }
    { const char * tb_v14337 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14337; }
    { const char * tb_v14338 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v14338; }
    { const char * tb_v14339 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14339; }
    { const char * tb_v14340 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v14340; }
    { const char * tb_v14341 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14341; }
    { const char * tb_v14342 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v14342; }
    { const char * tb_v14343 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14343; }
    { const char * tb_v14344 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14344; }
    { const char * tb_v14345 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14345; }
    { const char * tb_v14346 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14346; }
    { const char * tb_v14347 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14347; }
    { const char * tb_v14348 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v14348; }
    { const char * tb_v14349 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14349; }
    { const char * tb_v14350 = "        free(m->hk); m->hk = nk; m->hcap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v14350; }
    { const char * tb_v14351 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14351; }
    { const char * tb_v14352 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14352; }
    { const char * tb_v14353 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14353; }
    { const char * tb_v14354 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v14354; }
    { const char * tb_v14355 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14355; }
    { const char * tb_v14356 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14356; }
    { const char * tb_v14357 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14357; }
    { const char * tb_v14358 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v14358; }
    { const char * tb_v14359 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14359; }
    { const char * tb_v14360 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14360; }
    { const char * tb_v14361 = "        if (m->sb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14361; }
    { const char * tb_v14362 = "            m->sb = (int16_t *)realloc(m->sb, sizeof(int16_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14362; }
    { const char * tb_v14363 = "            m->sw = (float *)realloc(m->sw, sizeof(float) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14363; }
    { const char * tb_v14364 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14364; }
    { const char * tb_v14365 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14365; }
    { const char * tb_v14366 = "    if (m->sb) for (int i = 0; i < 4; i++) { m->sb[4 * m->nv + i] = -1; m->sw[4 * m->nv + i] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14366; }
    { const char * tb_v14367 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v14367; }
    { const char * tb_v14368 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14368; }
    { const char * tb_v14369 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14369; }
    { const char * tb_v14370 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14370; }
    { const char * tb_v14371 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v14371; }
    { const char * tb_v14372 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v14372; }
