    { const char * tb_v14443 = "TB_API double tb_amb0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14443; }
    { const char * tb_v14444 = "TB_API void tb_light(double dx, double dy, double dz, double amb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14444; }
    { const char * tb_v14445 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14445; }
    { const char * tb_v14446 = "    double l = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v14446; }
