    { const char * tb_v14468 = "// цвет грани под светом L (x, y, z, фон) — L уже в осях сетки; front — грань смотрит на нас\n"; *(const char * *)tb_grow(v_lines) = tb_v14468; }
    { const char * tb_v14469 = "// (со спины свет считается от обратной стороны: у пола и листа обе стороны освещены честно)\n"; *(const char * *)tb_grow(v_lines) = tb_v14469; }
    { const char * tb_v14470 = "TB_INL uint32_t tb_shade(uint32_t c, const int32_t *n, const int32_t *L, int front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14470; }
    { const char * tb_v14471 = "    if (L[3] < 0) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v14471; }
    { const char * tb_v14472 = "    int s = n[0] * L[0] + n[1] * L[1] + n[2] * L[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14472; }
    { const char * tb_v14473 = "    if (!front) s = -s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14473; }
    { const char * tb_v14474 = "    if (s < 0) s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14474; }
    { const char * tb_v14475 = "    int k = L[3] + (((256 - L[3]) * (s >> 14)) >> 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v14475; }
    { const char * tb_v14476 = "    uint32_t r = (((c >> 16) & 255) * (uint32_t)k + 128) >> 8, g = (((c >> 8) & 255) * (uint32_t)k + 128) >> 8, b = ((c & 255) * (uint32_t)k + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v14476; }
    { const char * tb_v14477 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v14477; }
    { const char * tb_v14478 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14478; }
    { const char * tb_v14479 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v14479; }
    { const char * tb_v14480 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14480; }
    { const char * tb_v14481 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v14481; }
    { const char * tb_v14482 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v14482; }
    { const char * tb_v14483 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v14483; }
    { const char * tb_v14484 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v14484; }
    { const char * tb_v14485 = "    double ax = ((dd[1] - dd[0]) * e2y - (dd[2] - dd[0]) * e1y) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v14485; }
    { const char * tb_v14486 = "    double by = ((dd[2] - dd[0]) * e1x - (dd[1] - dd[0]) * e2x) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v14486; }
    { const char * tb_v14487 = "    if (ax > 1e9) ax = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14487; }
    { const char * tb_v14488 = "    if (ax < -1e9) ax = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14488; }
    { const char * tb_v14489 = "    if (by > 1e9) by = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14489; }
    { const char * tb_v14490 = "    if (by < -1e9) by = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14490; }
    { const char * tb_v14491 = "    double c0 = dd[0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v14491; }
    { const char * tb_v14492 = "    // в целые: точка берётся по центру (2x + 1) / 2, поэтому ax / 2; ещё × 64 для точности\n"; *(const char * *)tb_grow(v_lines) = tb_v14492; }
    { const char * tb_v14493 = "    pl[0] = (uint32_t)tb_rnd(ax * 32); pl[1] = (uint32_t)tb_rnd(by * 32); pl[2] = (uint32_t)tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v14493; }
    { const char * tb_v14494 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14494; }
    { const char * tb_v14495 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14495; }
    { const char * tb_v14496 = "// углы сетки после камеры: место перед камерой и на экране (округлённое), глубина D\n"; *(const char * *)tb_grow(v_lines) = tb_v14496; }
    { const char * tb_v14497 = "typedef struct { double cx, cy, cz, sx, sy, dd; long long rx, ry; int front, near_ok; } tb_3v;\n"; *(const char * *)tb_grow(v_lines) = tb_v14497; }
    { const char * tb_v14498 = "TB_API tb_3v *tb_3vs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14498; }
