    { const char * tb_v14962 = "    for (int k = 0; k < 3; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14962; }
    { const char * tb_v14963 = "        for (int j = 0; j < 3; j++) go.rec.r[4 * k + j] = (int32_t)tb_rnd(M[k][j] * 1073741824.0);   // |M| <= 1: в 2^30 влезает\n"; *(const char * *)tb_grow(v_lines) = tb_v14963; }
    { const char * tb_v14964 = "        go.rec.r[4 * k + 3] = fabs(T[k]) < 400000 ? (int32_t)tb_rnd(T[k] * 4096) : 0;   // дальше — только старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v14964; }
    { const char * tb_v14965 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14965; }
