    { const char * tb_v14967 = "    for (int k = 0; k < 3; k++) go.rec.r[12 + k] = (int32_t)tb_rnd((R[0][k] * tb_lt[0] + R[1][k] * tb_lt[1] + R[2][k] * tb_lt[2]) * 16384);\n"; *(const char * *)tb_grow(v_lines) = tb_v14967; }
    { const char * tb_v14968 = "    go.rec.r[15] = tb_lamb;\n"; *(const char * *)tb_grow(v_lines) = tb_v14968; }
    { const char * tb_v14969 = "    const int32_t *L = go.rec.r + 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v14969; }
    { const char * tb_v14970 = "    if (st == 1) { tb_m3_draw(&go, 0, m->n); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14970; }
    { const char * tb_v14971 = "    if (m->nch <= 1) { tb_draw_mesh_d(m, x, y, z, R, L, 0, m->n); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14971; }
    { const char * tb_v14972 = "    // сетка большая и задевает камеру или край: по кускам — дальние на видеокарте, ближние старым путём\n"; *(const char * *)tb_grow(v_lines) = tb_v14972; }
    { const char * tb_v14973 = "    for (long long c = 0; c < m->nch; c++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14973; }
