    { const char * tb_v14975 = "        int cs = tb_m3_test(m->chs + 4 * c, M, T, f, m->big);\n"; *(const char * *)tb_grow(v_lines) = tb_v14975; }
    { const char * tb_v14976 = "        if (cs == 1) tb_m3_draw(&go, t0, tn);\n"; *(const char * *)tb_grow(v_lines) = tb_v14976; }
    { const char * tb_v14977 = "        else if (cs == 2) tb_draw_mesh_d(m, x, y, z, R, L, t0, t0 + tn);\n"; *(const char * *)tb_grow(v_lines) = tb_v14977; }
    { const char * tb_v14978 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14978; }
    { const char * tb_v14979 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14979; }
    { const char * tb_v14980 = "// ======== 3D (1.3): свет по углам, лампы, туман, тени, прозрачность, кости ========\n"; *(const char * *)tb_grow(v_lines) = tb_v14980; }
    { const char * tb_v14981 = "// Сетка с этими вещами считается на процессоре дробями: кости, место каждого угла в мире, свет каждого угла\n"; *(const char * *)tb_grow(v_lines) = tb_v14981; }
    { const char * tb_v14982 = "// (солнце, лампы, блик), место в тени, обрезка у камеры и рамкой вокруг окна. А точки внутри треугольника —\n"; *(const char * *)tb_grow(v_lines) = tb_v14982; }
    { const char * tb_v14983 = "// целыми числами одной формулой и на процессоре (tb_lit_px), и на видеокарте (tbl.frag, tb_fragl в tb3.metal):\n"; *(const char * *)tb_grow(v_lines) = tb_v14983; }
    { const char * tb_v14984 = "// значение в точке = (e0·v0·W0 + e1·v1·W1 + e2·v2·W2) / (e0·W0 + e1·W1 + e2·W2), где e — те же «стороны», что решают,\n"; *(const char * *)tb_grow(v_lines) = tb_v14984; }
    { const char * tb_v14985 = "// внутри ли точка (tb_tri_edge), а W — 1/z угла (так свет и тени ложатся с перспективой). Кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v14985; }
    { const char * tb_v14986 = "TB_INL double tb_fmin(double a, double b) { return a < b ? a : b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14986; }
    { const char * tb_v14987 = "TB_INL double tb_fmax(double a, double b) { return a > b ? a : b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14987; }
    { const char * tb_v14988 = "typedef struct { int on, spot; double p[3], d[3], c0, c1, range, col[3]; } tb_lamp_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v14988; }
    { const char * tb_v14989 = "TB_API tb_lamp_t tb_lamps[8];\n"; *(const char * *)tb_grow(v_lines) = tb_v14989; }
    { const char * tb_v14990 = "TB_API int tb_nlamps = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14990; }
    { const char * tb_v14991 = "TB_API double tb_amb0 = 0;               // фон, когда солнца нет (sunlight(0, 0, 0, фон)), а лампы горят\n"; *(const char * *)tb_grow(v_lines) = tb_v14991; }
    { const char * tb_v14992 = "TB_API int tb_fog_on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14992; }
    { const char * tb_v14993 = "TB_API uint32_t tb_fog_c = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14993; }
    { const char * tb_v14994 = "TB_API double tb_fog_n = 0, tb_fog_f = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14994; }
    { const char * tb_v14995 = "TB_API double tb_sh_size = 0;            // тени: сторона квадрата вокруг камеры (0 — теней нет)\n"; *(const char * *)tb_grow(v_lines) = tb_v14995; }
    { const char * tb_v14996 = "TB_API uint32_t *tb_sm = 0;              // карта теней (процессор): глубина от солнца, 0…65535\n"; *(const char * *)tb_grow(v_lines) = tb_v14996; }
    { const char * tb_v14997 = "TB_API long long tb_sm_ver = 0;          // номер карты (растёт при каждой новой)\n"; *(const char * *)tb_grow(v_lines) = tb_v14997; }
    { const char * tb_v14998 = "TB_API int tb_sm_live = 0;               // карта этой сцены готова: треугольники сцены знают про тени\n"; *(const char * *)tb_grow(v_lines) = tb_v14998; }
    { const char * tb_v14999 = "TB_API double tb_smC[3], tb_smR[3], tb_smU[3], tb_smF[3], tb_smT;   // квадрат теней: центр, оси, размер точки карты\n"; *(const char * *)tb_grow(v_lines) = tb_v14999; }
    { const char * tb_v15000 = "// видеокарта: какая карта теней лежит в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v15000; }
    { const char * tb_v15001 = "TB_API long long tb_gsm_batch = -1, tb_gsm_ver = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v15001; }
    { const char * tb_v15002 = "TB_INL int tb_lit_on(void) { return tb_lamb >= 0 || tb_nlamps > 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v15002; }
    { const char * tb_v15003 = "// сетка рисуется новым путём? (свои настройки сетки или что-то общее для всей сцены)\n"; *(const char * *)tb_grow(v_lines) = tb_v15003; }
