    { const char * tb_v16501 = "    long long now = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v16501; }
    { const char * tb_v16502 = "    if (now - tb_pad_look > 2000) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16502; }
