    { const char * tb_v16516 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16516; }
    { const char * tb_v16517 = "        struct { unsigned int time; short value; unsigned char type, number; } e;\n"; *(const char * *)tb_grow(v_lines) = tb_v16517; }
    { const char * tb_v16518 = "        long long got;\n"; *(const char * *)tb_grow(v_lines) = tb_v16518; }
    { const char * tb_v16519 = "        while ((got = read(tb_pad_fd[i], &e, sizeof e)) == (long long)sizeof e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16519; }
    { const char * tb_v16520 = "            int t = e.type & 0x7f;\n"; *(const char * *)tb_grow(v_lines) = tb_v16520; }
    { const char * tb_v16521 = "            if (t == 1 && e.number < 11) p->b[bmap[e.number]] = e.value != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16521; }
    { const char * tb_v16522 = "            else if (t == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16522; }
    { const char * tb_v16523 = "                double v = e.value / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16523; }
    { const char * tb_v16524 = "                if (v < -1) v = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16524; }
