    { const char * tb_v16949 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v16949; }
    { const char * tb_v16950 = "    if (sz < 12 || memcmp(b, \"RIFF\", 4) != 0 || memcmp(b + 8, \"WAVE\", 4) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16950; }
    { const char * tb_v16951 = "        tb_err = sz >= 4 && memcmp(b, \"OggS\", 4) == 0 ? \"OGG пока не умею: сохрани звук как WAV\" : \"это не WAV-файл\";\n"; *(const char * *)tb_grow(v_lines) = tb_v16951; }
    { const char * tb_v16952 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v16952; }
