    { const char * tb_v16957 = "    uint32_t dlen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16957; }
    { const char * tb_v16958 = "    long p = 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v16958; }
    { const char * tb_v16959 = "    while (p + 8 <= sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16959; }
