    { const char * tb_v16970 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16970; }
    { const char * tb_v16971 = "    int okf = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32)) || (tag == 3 && (bits == 32 || bits == 64));\n"; *(const char * *)tb_grow(v_lines) = tb_v16971; }
    { const char * tb_v16972 = "    if (!data || !okf || ch == 0 || rate == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16972; }
    { const char * tb_v16973 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v16973; }
    { const char * tb_v16974 = "        tb_err = !data ? \"в WAV нет звука (нет куска data)\" : \"такой WAV не умею: нужен PCM 8/16/24/32 бита или float\";\n"; *(const char * *)tb_grow(v_lines) = tb_v16974; }
    { const char * tb_v16975 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16975; }
