    { const char * tb_v17038 = "// тон: синус hz герц на ms миллисекунд, мягкое начало и конец (без щелчков)\n"; *(const char * *)tb_grow(v_lines) = tb_v17038; }
    { const char * tb_v17039 = "TB_API long long tb_play_tone(double hz, long long ms) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17039; }
    { const char * tb_v17040 = "    if (ms <= 0 || hz <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17040; }
    { const char * tb_v17041 = "    if (ms > 60000) ms = 60000;\n"; *(const char * *)tb_grow(v_lines) = tb_v17041; }
    { const char * tb_v17042 = "    long long n = ms * TB_SR / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v17042; }
    { const char * tb_v17043 = "    float *d = malloc(sizeof(float) * (size_t)(n + 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v17043; }
    { const char * tb_v17044 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17044; }
    { const char * tb_v17045 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v17045; }
    { const char * tb_v17046 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v17046; }
    { const char * tb_v17047 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17047; }
    { const char * tb_v17048 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17048; }
