    { const char * tb_v17050 = "        else if (i >= n - ramp) e = (double)(n - 1 - i) / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v17050; }
    { const char * tb_v17051 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v17051; }
    { const char * tb_v17052 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17052; }
