    { const char * tb_v17564 = "                r_info, = struct.unpack_from(\"<Q\", data, s[\"off\"] + k * 24 + 8)\n"; *(const char * *)tb_grow(v_lines) = tb_v17564; }
    { const char * tb_v17565 = "                if r_info & 0xFFFFFFFF in (9, 41, 42) and r_info >> 32 not in got_syms:\n"; *(const char * *)tb_grow(v_lines) = tb_v17565; }
