    { const char * tb_v17634 = "            v = st_value\n"; *(const char * *)tb_grow(v_lines) = tb_v17634; }
    { const char * tb_v17635 = "        elif st_shndx == SHN_COMMON:\n"; *(const char * *)tb_grow(v_lines) = tb_v17635; }
