    { const char * tb_v17664 = "        image[strs_at - BASE + so:strs_at - BASE + so + len(n)] = n\n"; *(const char * *)tb_grow(v_lines) = tb_v17664; }
    { const char * tb_v17665 = "        so += len(n) + 1\n"; *(const char * *)tb_grow(v_lines) = tb_v17665; }
    { const char * tb_v17666 = "    vd = dict(values)\n"; *(const char * *)tb_grow(v_lines) = tb_v17666; }
    { const char * tb_v17667 = "    for nm, val in ((\"tb_ksym_tab\", ksym_at), (\"tb_ksym_n\", len(allx))):\n"; *(const char * *)tb_grow(v_lines) = tb_v17667; }
